internal sealed class Parser(IReadOnlyList<Token> tokens, bool isStandardLibrary = false, IReadOnlyDictionary<string, IReadOnlyList<OpenImportCandidate>>? openImports = null)
{
    private int _index;
    private int _syntheticBlockResultIndex;
    private IReadOnlyList<string> _namespacePath = [];
    private readonly Dictionary<string, IReadOnlyList<string>> _imports = new(StringComparer.Ordinal);
    private readonly Dictionary<string, IReadOnlyList<string>> _libraryImports = new(StringComparer.Ordinal);
    private readonly IReadOnlyDictionary<string, IReadOnlyList<OpenImportCandidate>> _openImports = openImports ?? new Dictionary<string, IReadOnlyList<OpenImportCandidate>>(StringComparer.Ordinal);
    private readonly HashSet<string> _activeAssociatedTypeNames = new(StringComparer.Ordinal);
    private readonly HashSet<string> _activeGenericParameterNames = new(StringComparer.Ordinal);
    private readonly List<StructDeclaration> _nestedStructs = [];
    private readonly HashSet<string> _knownNestedTypeNames = new(StringComparer.Ordinal);
    private readonly Stack<string> _activeTypeScopes = new();

    public SollangProgram Parse()
    {
        // SourceFile = NewLine* NamespaceDeclaration? ImportDeclaration* FunctionDeclaration* (MainBlock | Statement*) NewLine* End
        var structs = new List<StructDeclaration>();
        var enums = new List<EnumDeclaration>();
        var traits = new List<TraitDeclaration>();
        var functions = new List<FunctionDeclaration>();
        List<NativeLibraryImport>? nativeLibraries = null;
        SkipNewLines();
        if (CheckIdentifier("namespace"))
        {
            ParseNamespaceDeclaration();
            SkipNewLines();
        }

        while (CheckIdentifier("import"))
        {
            ParseImportDeclaration();
            SkipNewLines();
        }

        while (CheckIdentifier("library"))
        {
            (nativeLibraries ??= []).Add(ParseLibraryImportDeclaration());
            SkipNewLines();
        }

        while (true)
        {
            if (CheckStructDeclarationStart())
            {
                structs.Add(ParseStructDeclaration());
            }
            else if (CheckDeclarationStart("enum"))
            {
                enums.Add(ParseEnumDeclaration());
            }
            else if (CheckDeclarationStart("trait"))
            {
                traits.Add(ParseTraitDeclaration());
            }
            else if (CheckIdentifier("impl"))
            {
                functions.AddRange(ParseImplDeclaration());
            }
            else if (CheckIdentifier("com"))
            {
                ParseComLibraryDeclaration(structs, functions);
            }
            else if (CheckIdentifier("native"))
            {
                functions.AddRange(ParseNativeLibraryDeclaration(structs));
            }
            else if (IsFunctionDeclarationStart())
            {
                functions.Add(ParseFunctionDeclaration(isLocal: false));
            }
            else
            {
                break;
            }
            SkipNewLines();
        }
        structs.AddRange(_nestedStructs);

        var statements = CheckIdentifier("main")
            ? ParseMainBlock()
            : ParseTopLevelStatements();
        SkipNewLines();
        Expect(TokenKind.End);
        var imports = _imports.Select(static pair => new ImportDeclaration(pair.Value, pair.Key)).ToArray();
        return new SollangProgram(_namespacePath, imports, structs, enums, traits, functions, statements, nativeLibraries, SourceStyleAnalyzer.Analyze(tokens, string.Join('.', _namespacePath)));
    }

    public Expression ParseExpressionFragment()
    {
        SkipNewLines();
        var expression = ParseExpression();
        SkipNewLines();
        Expect(TokenKind.End);
        return expression;
    }

    private Expression ParseInterpolationExpressionFragment(string text, Token origin)
    {
        var tokens = new Lexer(text).Lex().Select(token => token with
        {
            ByteOffset = origin.ByteOffset < 0 ? -1 : origin.ByteOffset + token.ByteOffset,
            SourceLine = origin.SourceLine + token.Line - 1,
            SourceColumn = token.Line == 1 ? origin.SourceColumn + token.Column - 1 : token.Column
        }).ToArray();
        var fragment = new Parser(tokens, isStandardLibrary, _openImports);
        fragment._namespacePath = _namespacePath;
        foreach (var (alias, path) in _imports) fragment._imports.Add(alias, path);
        foreach (var name in _activeAssociatedTypeNames) fragment._activeAssociatedTypeNames.Add(name);
        foreach (var name in _activeGenericParameterNames) fragment._activeGenericParameterNames.Add(name);
        foreach (var name in _knownNestedTypeNames) fragment._knownNestedTypeNames.Add(name);
        foreach (var scope in _activeTypeScopes.Reverse()) fragment._activeTypeScopes.Push(scope);
        return fragment.ParseExpressionFragment();
    }

    private void ParseNamespaceDeclaration()
    {
        // NamespaceDeclaration = Identifier("namespace") Path StatementEnd
        ExpectIdentifier("namespace");
        var start = ExpectIdentifier();
        _namespacePath = ParsePathAfterFirstIdentifier(start);
        ExpectStatementEnd();
    }

    private void ParseImportDeclaration()
    {
        // ImportDeclaration = Identifier("import") Path (Identifier("as") Identifier)? StatementEnd
        var importToken = ExpectIdentifier("import");
        var start = ExpectIdentifier();
        var path = ParsePathAfterFirstIdentifier(start);
        var alias = path[path.Count - 1];
        if (CheckIdentifier("as"))
        {
            ExpectIdentifier("as");
            alias = ExpectIdentifier().Text;
        }

        if (_imports.ContainsKey(alias))
        {
            throw Error(importToken, $"import alias '{alias}' already exists");
        }

        _imports.Add(alias, path);
        ExpectStatementEnd();
    }

    private StructDeclaration ParseStructDeclaration(string? declaringTypeName = null)
    {
        // StructDeclaration = Identifier("public")? AbiMarker? Identifier("struct") Identifier LeftBrace NewLine* StructFieldDeclaration* RightBrace
        var isPublic = CheckIdentifier("public");
        if (isPublic) ExpectIdentifier("public");
        var isAbi = CheckIdentifier("abi");
        if (isAbi) ExpectIdentifier("abi");
        var keyword = ExpectIdentifier("struct");
        var name = ExpectIdentifier();
        var declarationName = declaringTypeName is null ? QualifyTypeDeclarationName(name.Text) : declaringTypeName + "." + name.Text;
        if (declaringTypeName is not null) _knownNestedTypeNames.Add(declarationName);
        Expect(TokenKind.LeftBrace);
        _activeTypeScopes.Push(declarationName);
        SkipNewLines();
        var fields = new List<StructFieldDeclaration>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            if (CheckStructDeclarationStart())
            {
                _nestedStructs.Add(ParseStructDeclaration(declarationName));
                SkipNewLines();
                continue;
            }
            var isFieldPublic = CheckIdentifier("public");
            if (isFieldPublic) ExpectIdentifier("public");
            var field = ExpectIdentifier();
            Expect(TokenKind.Colon);
            var fieldType = ParseTypeAnnotation();
            var hadComma = Match(TokenKind.Comma, out _);
            fields.Add(new StructFieldDeclaration(field.Text, fieldType, field.Line, field.Column, isFieldPublic));
            if (!hadComma && !Check(TokenKind.NewLine) && !Check(TokenKind.RightBrace))
            {
                throw Error(Peek(), "struct fields must be separated by a newline");
            }
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        _activeTypeScopes.Pop();
        return new StructDeclaration(declarationName, fields, keyword.Line, keyword.Column, string.Join('.', _namespacePath), isPublic, declaringTypeName, isAbi);
    }

    private EnumDeclaration ParseEnumDeclaration()
    {
        // EnumDeclaration = Identifier("enum") Identifier LeftBrace NewLine* EnumVariantDeclaration* RightBrace
        var isPublic = CheckIdentifier("public");
        if (isPublic) ExpectIdentifier("public");
        var keyword = ExpectIdentifier("enum");
        var name = ExpectIdentifier();
        var declarationName = QualifyTypeDeclarationName(name.Text);
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var variants = new List<EnumVariantDeclaration>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            var variant = ExpectIdentifier();
            string? payloadType = null;
            if (Match(TokenKind.LeftParen, out _))
            {
                payloadType = ParseTypeAnnotation();
                Expect(TokenKind.RightParen);
            }
            var hadComma = Match(TokenKind.Comma, out _);
            variants.Add(new EnumVariantDeclaration(variant.Text, payloadType, variant.Line, variant.Column));
            if (!hadComma && !Check(TokenKind.NewLine) && !Check(TokenKind.RightBrace))
            {
                throw Error(Peek(), "enum variants must be separated by a comma or newline");
            }
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        return new EnumDeclaration(declarationName, variants, keyword.Line, keyword.Column, string.Join('.', _namespacePath), isPublic);
    }

    private TraitDeclaration ParseTraitDeclaration()
    {
        var isPublic = CheckIdentifier("public");
        if (isPublic) ExpectIdentifier("public");
        var keyword = ExpectIdentifier("trait");
        var name = ExpectIdentifier();
        var declarationName = QualifyTypeDeclarationName(name.Text);
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var associatedTypes = new List<TraitAssociatedTypeDeclaration>();
        var methods = new List<TraitMethodDeclaration>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            if (CheckIdentifier("type"))
            {
                ExpectIdentifier("type");
                var associatedType = ExpectIdentifier();
                if (!_activeAssociatedTypeNames.Add(associatedType.Text))
                {
                    throw Error(associatedType, $"associated type '{associatedType.Text}' already exists");
                }
                associatedTypes.Add(new TraitAssociatedTypeDeclaration(associatedType.Text, associatedType.Line, associatedType.Column));
                ExpectStatementEnd();
                SkipNewLines();
                continue;
            }
            var method = ExpectIdentifier();
            Expect(TokenKind.Colon);
            var ownership = FunctionInputOwnership.Default;
            if (CheckIdentifier("move"))
            {
                ExpectIdentifier("move");
                ownership = FunctionInputOwnership.Move;
            }
            else if (CheckIdentifier("mut"))
            {
                ExpectIdentifier("mut");
                ownership = FunctionInputOwnership.MutableBorrow;
            }
            ExpectIdentifier("self");
            var parameters = new List<FunctionParameterDeclaration>();
            while (Match(TokenKind.Comma, out _))
            {
                var parameterName = ExpectIdentifier();
                Expect(TokenKind.Colon);
                var signature = ParseRequiredInputSignature();
                parameters.Add(new FunctionParameterDeclaration(parameterName.Text, signature.TypeName!, signature.Ownership, parameterName.Line, parameterName.Column));
            }
            Expect(TokenKind.Arrow);
            var returnType = ParseTypeAnnotation();
            ExpectStatementEnd();
            methods.Add(new TraitMethodDeclaration(method.Text, ownership, returnType, method.Line, method.Column, parameters));
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        _activeAssociatedTypeNames.Clear();
        return new TraitDeclaration(declarationName, associatedTypes, methods, keyword.Line, keyword.Column, string.Join('.', _namespacePath), isPublic);
    }

    private IReadOnlyList<FunctionDeclaration> ParseImplDeclaration()
    {
        // ImplDeclaration permits a nominal/builtin Path or a concrete array storage type as its owner.
        ExpectIdentifier("impl");
        var firstType = ParseImplOwnerType();
        string? traitName = null;
        var ownerType = firstType;
        if (CheckIdentifier("for"))
        {
            ExpectIdentifier("for");
            traitName = firstType;
            ownerType = ParseImplOwnerType();
        }
        Expect(TokenKind.LeftBrace);
        _activeTypeScopes.Push(ownerType);
        SkipNewLines();
        var implAssociatedTypes = new Dictionary<string, string>(StringComparer.Ordinal);
        while (CheckIdentifier("type"))
        {
            var typeKeyword = ExpectIdentifier("type");
            var associatedType = ExpectIdentifier();
            Expect(TokenKind.Equal);
            var concreteType = ParseTypeAnnotation();
            if (!implAssociatedTypes.TryAdd(associatedType.Text, concreteType))
            {
                throw Error(typeKeyword, $"associated type '{associatedType.Text}' is bound more than once");
            }
            ExpectStatementEnd();
            SkipNewLines();
        }
        var methods = new List<FunctionDeclaration>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            if (!IsFunctionDeclarationStart())
            {
                throw Error(Peek(), "expected method declaration");
            }
            methods.Add(ParseFunctionDeclaration(isLocal: false, methodOwner: ownerType, traitName: traitName, implAssociatedTypes: implAssociatedTypes));
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        _activeTypeScopes.Pop();
        return methods;
    }

    private string ParseImplOwnerType()
    {
        if (Check(TokenKind.LeftBracket))
        {
            return ParseTypeAnnotation();
        }

        var ownerTypeToken = ExpectIdentifier();
        return ResolveTypePath(ParsePathAfterFirstIdentifier(ownerTypeToken));
    }

    private void ParseComLibraryDeclaration(
        List<StructDeclaration> structs,
        List<FunctionDeclaration> functions)
    {
        var keyword = ExpectIdentifier("com");
        var alias = ExpectIdentifier();
        ExpectIdentifier("class");
        var classId = Expect(TokenKind.String).Text;
        string? server = null;
        if (CheckIdentifier("from"))
        {
            ExpectIdentifier("from");
            server = Expect(TokenKind.String).Text;
            if (server.Length == 0)
            {
                throw Error(keyword, "COM server name must not be empty");
            }
        }
        ExpectIdentifier("in");
        var apartmentToken = ExpectIdentifier();
        var apartment = apartmentToken.Text switch
        {
            "sta" => ComApartment.Sta,
            "mta" => ComApartment.Mta,
            _ => throw Error(apartmentToken, "COM apartment must be 'sta' or 'mta'")
        };
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var interfaceIndex = 0;
        var parsedInterfaces = new List<(Token Name, string Type, string Id)>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            ExpectIdentifier("interface");
            var interfaceName = ExpectIdentifier();
            var interfaceId = Expect(TokenKind.String).Text;
            var interfaceType = alias.Text + "." + interfaceName.Text;
            var metadata = new ComInterfaceMetadata(
                alias.Text, classId, interfaceId, server, apartment);
            structs.Add(new StructDeclaration(
                interfaceType,
                [new StructFieldDeclaration("handle", "UInt64", interfaceName.Line, interfaceName.Column)],
                interfaceName.Line,
                interfaceName.Column,
                string.Join('.', _namespacePath),
                IsPublic: false,
                ComInterface: metadata));

            var createName = interfaceIndex == 0
                ? alias.Text + ".create"
                : alias.Text + ".create" + interfaceName.Text;
            functions.Add(new FunctionDeclaration(
                createName, null, null, FunctionInputOwnership.Default,
                "Result<" + interfaceType + ", Int32>",
                null, null, [], null, [],
                interfaceName.Line, interfaceName.Column,
                false, false,
                ModuleName: string.Join('.', _namespacePath),
                Com: new ComFunctionMetadata(
                    ComFunctionOperation.Activate, interfaceType, classId, interfaceId, server, apartment)));

            var cloneName = interfaceIndex == 0
                ? alias.Text + ".clone"
                : alias.Text + ".clone" + interfaceName.Text;
            functions.Add(new FunctionDeclaration(
                cloneName, "self", "ref " + interfaceType, FunctionInputOwnership.Default,
                interfaceType, null, null, [], null, [],
                interfaceName.Line, interfaceName.Column,
                false, false,
                ModuleName: string.Join('.', _namespacePath),
                Com: new ComFunctionMetadata(
                    ComFunctionOperation.Clone, interfaceType, classId, interfaceId, server, apartment)));

            Expect(TokenKind.LeftBrace);
            SkipNewLines();
            while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
            {
                var method = ParseFunctionDeclaration(
                    isLocal: false, nativeAlias: alias.Text, signatureOnly: true);
                ExpectIdentifier("at");
                var slotToken = Expect(TokenKind.Number);
                if (!int.TryParse(slotToken.Text, out var slot) || slot < 3)
                {
                    throw Error(slotToken, "COM vtable slot must be an integer greater than or equal to 3");
                }
                var parameters = new List<FunctionParameterDeclaration>();
                if (method.InputType is not null)
                {
                    parameters.Add(new FunctionParameterDeclaration(
                        method.InputName ?? "it", method.InputType, method.InputOwnership,
                        method.Line, method.Column));
                }
                parameters.AddRange(method.AdditionalParameters ?? []);
                functions.Add(method with
                {
                    InputName = "self",
                    InputType = "ref " + interfaceType,
                    InputOwnership = FunctionInputOwnership.Default,
                    AdditionalParameters = parameters,
                    NativeLibrary = null,
                    NativeSymbol = null,
                    Com = new ComFunctionMetadata(
                        ComFunctionOperation.Method, interfaceType, classId, interfaceId,
                        server, apartment, slot)
                });
                SkipNewLines();
            }
            Expect(TokenKind.RightBrace);

            foreach (var previous in parsedInterfaces)
            {
                AddComQueryFunction(
                    functions, alias.Text, classId, server, apartment,
                    previous.Name, previous.Type,
                    interfaceName, interfaceType, interfaceId);
                AddComQueryFunction(
                    functions, alias.Text, classId, server, apartment,
                    interfaceName, interfaceType,
                    previous.Name, previous.Type, previous.Id);
            }
            parsedInterfaces.Add((interfaceName, interfaceType, interfaceId));
            interfaceIndex++;
            SkipNewLines();
        }
        if (interfaceIndex == 0)
        {
            throw Error(keyword, "COM declaration requires at least one interface");
        }
        Expect(TokenKind.RightBrace);
    }

    private void AddComQueryFunction(
        List<FunctionDeclaration> functions,
        string alias,
        string classId,
        string? server,
        ComApartment apartment,
        Token sourceName,
        string sourceType,
        Token targetName,
        string targetType,
        string targetId)
    {
        functions.Add(new FunctionDeclaration(
            alias + ".query" + targetName.Text + "From" + sourceName.Text,
            "self", "ref " + sourceType, FunctionInputOwnership.Default,
            "Result<" + targetType + ", Int32>",
            null, null, [], null, [],
            targetName.Line, targetName.Column,
            false, false,
            ModuleName: string.Join('.', _namespacePath),
            Com: new ComFunctionMetadata(
                ComFunctionOperation.Query, targetType, classId, targetId,
                server, apartment, ReceiverInterfaceType: sourceType)));
    }

    private NativeLibraryImport ParseLibraryImportDeclaration()
    {
        var keyword = ExpectIdentifier("library");
        var alias = ExpectIdentifier();
        ExpectIdentifier("from");
        var library = Expect(TokenKind.String).Text;
        if (library.Length == 0)
        {
            throw Error(keyword, "library name must not be empty");
        }
        ExpectStatementEnd();
        _libraryImports[alias.Text] = _namespacePath.Append(alias.Text).ToArray();
        return new NativeLibraryImport(alias.Text, library, keyword.Line, keyword.Column);
    }

    private IReadOnlyList<FunctionDeclaration> ParseNativeLibraryDeclaration(List<StructDeclaration> structs)
    {
        var keyword = ExpectIdentifier("native");
        var alias = ExpectIdentifier();
        ExpectIdentifier("from");
        var library = Expect(TokenKind.String).Text;
        if (library.Length == 0)
        {
            throw Error(keyword, "native library name must not be empty");
        }
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var functions = new List<FunctionDeclaration>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            if (CheckIdentifier("handle"))
            {
                ExpectIdentifier("handle");
                var handleName = ExpectIdentifier();
                ExpectIdentifier("drop");
                var dropSymbol = Expect(TokenKind.String).Text;
                if (dropSymbol.Length == 0)
                {
                    throw Error(handleName, "native handle drop symbol must not be empty");
                }
                var qualifiedName = alias.Text + "." + handleName.Text;
                structs.Add(new StructDeclaration(
                    qualifiedName,
                    [new StructFieldDeclaration("handle", "UInt64", handleName.Line, handleName.Column)],
                    handleName.Line, handleName.Column,
                    string.Join('.', _namespacePath),
                    IsPublic: false,
                    IsAbi: true,
                    NativeHandle: new NativeHandleMetadata(alias.Text, library, dropSymbol)));
                ExpectStatementEnd();
                SkipNewLines();
                continue;
            }
            var nativeError = NativeErrorConvention.Direct;
            if (CheckIdentifier("try"))
            {
                ExpectIdentifier("try");
                nativeError = NativeErrorConvention.StatusOut;
            }
            if (!IsFunctionDeclarationStart())
            {
                throw Error(Peek(), "expected a native function declaration");
            }
            var function = ParseFunctionDeclaration(
                isLocal: false, nativeLibraryOverride: library, nativeAlias: alias.Text);
            if (nativeError == NativeErrorConvention.StatusOut)
            {
                var successType = function.ReturnType;
                function = function with
                {
                    ReturnType = $"Result<{successType}, Int32>",
                    NativeError = nativeError,
                    NativeSuccessType = successType
                };
            }
            functions.Add(function);
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        return functions;
    }

    private FunctionDeclaration ParseFunctionDeclaration(bool isLocal, string? methodOwner = null, string? traitName = null, IReadOnlyDictionary<string, string>? implAssociatedTypes = null, string? nativeLibraryOverride = null, string? nativeAlias = null, bool signatureOnly = false)
    {
        // FunctionDeclaration = Path Identifier? Colon FunctionSignature (BlockFunctionBody | FunctionBody)
        var isPublic = false;
        if (CheckIdentifier("public"))
        {
            var publicToken = ExpectIdentifier("public");
            if (isLocal)
            {
                throw Error(publicToken, "local functions cannot be public");
            }
            isPublic = true;
        }
        var name = ExpectIdentifier();
        var namePath = ParsePathAfterFirstIdentifier(name);
        string? genericParameterName = null;
        string? secondaryGenericParameterName = null;
        string? tertiaryGenericParameterName = null;
        string? genericTraitBound = null;
        string? genericAssociatedTypeName = null;
        string? genericAssociatedTypeConstraint = null;
        var genericParameterTokens = new List<Token>();
        var genericConstraints = new Dictionary<string, List<GenericConstraintDeclaration>>(StringComparer.Ordinal);
        var isValueGeneric = false;
        if (Match(TokenKind.Less, out _))
        {
            while (true)
            {
                var parameter = ExpectIdentifier();
                if (!_activeGenericParameterNames.Add(parameter.Text))
                {
                    throw Error(parameter, $"generic parameter '{parameter.Text}' already exists");
                }
                genericParameterTokens.Add(parameter);
                genericConstraints[parameter.Text] = [];
                if (!Match(TokenKind.Comma, out _)) break;
            }
            Expect(TokenKind.Greater);
            genericParameterName = genericParameterTokens.Count > 0 ? genericParameterTokens[0].Text : null;
            secondaryGenericParameterName = genericParameterTokens.Count > 1 ? genericParameterTokens[1].Text : null;
            tertiaryGenericParameterName = genericParameterTokens.Count > 2 ? genericParameterTokens[2].Text : null;
        }
        if (methodOwner is not null && namePath.Count != 1)
        {
            throw Error(name, "method names cannot be path-qualified");
        }
        var qualifiedMethodOwner = methodOwner is null ? null : QualifyMethodOwner(methodOwner);
        var functionName = methodOwner is null
            ? QualifyFunctionName(namePath, isLocal)
            : traitName is null
                ? qualifiedMethodOwner + "." + name.Text
                : traitName + "." + qualifiedMethodOwner + "." + name.Text;
        if (nativeAlias is not null)
        {
            if (namePath.Count != 1)
            {
                throw Error(name, "native block member names cannot be path-qualified");
            }
            functionName = nativeAlias + "." + name.Text;
        }
        Token? inputName = null;
        if (methodOwner is null && Check(TokenKind.Identifier) && CheckNext(TokenKind.Colon))
        {
            inputName = ExpectIdentifier();
        }

        Expect(TokenKind.Colon);
        var inputSignature = methodOwner is null
            ? ParseOptionalInputSignature()
            : ParseOptionalSelfSignature(methodOwner, out inputName);
        var inputType = inputSignature.TypeName;
        var inputOwnership = inputSignature.Ownership;
        var additionalParameters = new List<FunctionParameterDeclaration>();
        while (Match(TokenKind.Comma, out _))
        {
            var parameterName = ExpectIdentifier();
            Expect(TokenKind.Colon);
            var parameterSignature = ParseRequiredInputSignature();
            additionalParameters.Add(new FunctionParameterDeclaration(
                parameterName.Text, parameterSignature.TypeName!, parameterSignature.Ownership,
                parameterName.Line, parameterName.Column));
        }
        var hasValueGenericFixedArrayInput = false;

        Expect(TokenKind.Arrow);
        var isAsync = false;
        string? streamElementType = null;
        if (CheckIdentifier("stream"))
        {
            ExpectIdentifier("stream");
            streamElementType = ParseTypeAnnotation();
        }
        else if (CheckIdentifier("async"))
        {
            ExpectIdentifier("async");
            isAsync = true;
        }
        string returnType;
        if (streamElementType is not null)
        {
            returnType = "Unit";
        }
        else if (Check(TokenKind.FatArrow) || Check(TokenKind.Arrow) || Check(TokenKind.Equal) || CheckIdentifier("uses"))
        {
            returnType = InferredFunctionType.Name;
        }
        else if (Check(TokenKind.LeftBrace))
        {
            var savedReturnTypeIndex = _index;
            try
            {
                returnType = ParseTypeAnnotation();
            }
            catch (SollangException)
            {
                _index = savedReturnTypeIndex;
                returnType = InferredFunctionType.Name;
            }
        }
        else
        {
            returnType = ParseTypeAnnotation();
        }
        var effects = new List<string>();
        if (CheckIdentifier("uses"))
        {
            ExpectIdentifier("uses");
            effects.Add(ExpectIdentifier().Text);
            while (Match(TokenKind.Comma, out _))
            {
                effects.Add(ExpectIdentifier().Text);
            }
        }
        if (CheckIdentifier("where"))
        {
            ExpectIdentifier("where");
            while (true)
            {
                var constrainedParameter = ExpectIdentifier();
                if (!genericConstraints.TryGetValue(constrainedParameter.Text, out var parameterConstraints))
                {
                    throw Error(constrainedParameter, $"unknown generic parameter '{constrainedParameter.Text}' in where clause");
                }
                if (Match(TokenKind.Dot, out _))
                {
                    var associatedType = ExpectIdentifier();
                    Expect(TokenKind.EqualEqual);
                    var equalType = ParseTypeAnnotation();
                    parameterConstraints.Add(new GenericConstraintDeclaration(
                        constrainedParameter.Text, null, associatedType.Text, equalType,
                        constrainedParameter.Line, constrainedParameter.Column));
                    if (constrainedParameter.Text == genericParameterName)
                    {
                        genericAssociatedTypeName = associatedType.Text;
                        genericAssociatedTypeConstraint = equalType;
                    }
                }
                else
                {
                    Expect(TokenKind.Colon);
                    var traitToken = ExpectIdentifier();
                    var traitBound = ResolveTypePath(ParsePathAfterFirstIdentifier(traitToken));
                    parameterConstraints.Add(new GenericConstraintDeclaration(
                        constrainedParameter.Text, traitBound, null, null,
                        constrainedParameter.Line, constrainedParameter.Column));
                    if (constrainedParameter.Text == genericParameterName && genericTraitBound is null)
                    {
                        genericTraitBound = traitBound;
                        isValueGeneric = traitBound == "Int";
                    }
                }
                if (!Match(TokenKind.Comma, out _)) break;
            }
        }
        hasValueGenericFixedArrayInput = isValueGeneric
            && inputType is not null
            && inputType.StartsWith('[', StringComparison.Ordinal)
            && inputType.EndsWith($"; {genericParameterName}]", StringComparison.Ordinal);
        if (methodOwner is not null && returnType == "Self")
        {
            returnType = methodOwner;
        }
        Token? blockInputName = null;
        string? blockInputType = null;
        var additionalBlockParameters = new List<FunctionParameterDeclaration>();
        string? blockResultType = null;
        var localFunctions = new List<FunctionDeclaration>();
        Expression? body = null;
        var blockBody = new List<Statement>();
        var isIntrinsic = false;
        string? nativeLibrary = nativeLibraryOverride;
        string? nativeSymbol = null;
        if (nativeLibraryOverride is not null && CheckIdentifier("as"))
        {
            ExpectIdentifier("as");
            nativeSymbol = Expect(TokenKind.String).Text;
            if (nativeSymbol.Length == 0)
            {
                throw Error(name, "native symbol name must not be empty");
            }
        }
        if (nativeLibraryOverride is not null || signatureOnly)
        {
            if (!signatureOnly && !Check(TokenKind.NewLine) && !Check(TokenKind.RightBrace))
            {
                throw Error(Peek(), "native block members contain only a signature");
            }
        }
        else if (CheckIdentifier("block"))
        {
            // BlockFunctionBody = Identifier("block") Identifier Colon TypeAnnotation (Arrow TypeAnnotation)? (LeftBrace BlockBody RightBrace | Equal Identifier("intrinsic"))
            ExpectIdentifier("block");
            blockInputName = ExpectIdentifier();
            Expect(TokenKind.Colon);
            blockInputType = ParseTypeAnnotation();
            while (Match(TokenKind.Comma, out _))
            {
                var parameterName = ExpectIdentifier();
                Expect(TokenKind.Colon);
                var parameterType = ParseTypeAnnotation();
                additionalBlockParameters.Add(new FunctionParameterDeclaration(
                    parameterName.Text, parameterType, FunctionInputOwnership.Default,
                    parameterName.Line, parameterName.Column));
            }
            if (Match(TokenKind.Arrow, out _))
            {
                blockResultType = ParseTypeAnnotation();
            }
            if (Match(TokenKind.Equal, out _))
            {
                ExpectIdentifier("intrinsic");
                isIntrinsic = true;
            }
            else
            {
                Expect(TokenKind.LeftBrace);
            SkipNewLines();
            if (returnType == "Unit")
            {
                while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
                {
                    blockBody.AddRange(ParseStatement());
                    SkipNewLines();
                }
            }
            else
            {
                var parsedBody = ParseFunctionBlockBody();
                blockBody.AddRange(parsedBody.Statements);
                body = parsedBody.Value;
            }
            Expect(TokenKind.RightBrace);
            }
        }
        else if (Match(TokenKind.Equal, out _))
        {
            if (CheckIdentifier("intrinsic"))
            {
                ExpectIdentifier("intrinsic");
                isIntrinsic = true;
            }
            else
            {
                ExpectIdentifier("native");
                nativeLibrary = Expect(TokenKind.String).Text;
            }
        }
        else if (Match(TokenKind.FatArrow, out _))
        {
            body = ParseExpression();
        }
        else
        {
            Expect(TokenKind.LeftBrace);
            SkipNewLines();
            while (IsFunctionDeclarationStart())
            {
                localFunctions.Add(ParseFunctionDeclaration(isLocal: true));
                SkipNewLines();
            }

            var parsedBody = ParseFunctionBlockBody();
            blockBody.AddRange(parsedBody.Statements);
            body = parsedBody.Value;
            Expect(TokenKind.RightBrace);
        }

        var genericParameters = genericParameterTokens
            .Select(parameter => new GenericParameterDeclaration(
                parameter.Text, genericConstraints[parameter.Text], parameter.Line, parameter.Column,
                genericConstraints[parameter.Text].Any(constraint => constraint.TraitName == "Int")))
            .ToArray();
        _activeGenericParameterNames.Clear();
        return new FunctionDeclaration(functionName, inputName?.Text, inputType, inputOwnership, returnType, blockInputName?.Text, blockInputType, localFunctions, body, blockBody, name.Line, name.Column, isIntrinsic, isStandardLibrary, traitName, genericParameterName, secondaryGenericParameterName, tertiaryGenericParameterName, genericTraitBound, genericAssociatedTypeName, genericAssociatedTypeConstraint, implAssociatedTypes, isValueGeneric, hasValueGenericFixedArrayInput, string.Join('.', _namespacePath), isPublic, isAsync, effects, blockResultType, additionalParameters, additionalBlockParameters, streamElementType, nativeLibrary, nativeSymbol, GenericParameters: genericParameters);
    }

    private FunctionInputSignature ParseOptionalSelfSignature(string ownerType, out Token? inputName)
    {
        inputName = null;
        if (Check(TokenKind.Arrow))
        {
            return new FunctionInputSignature(null, FunctionInputOwnership.Default);
        }
        var ownership = FunctionInputOwnership.Default;
        if (CheckIdentifier("move"))
        {
            ExpectIdentifier("move");
            ownership = FunctionInputOwnership.Move;
        }
        else if (CheckIdentifier("mut"))
        {
            ExpectIdentifier("mut");
            ownership = FunctionInputOwnership.MutableBorrow;
        }
        if (CheckIdentifier("self"))
        {
            inputName = ExpectIdentifier("self");
            return new FunctionInputSignature(ownerType, ownership);
        }
        if (ownership != FunctionInputOwnership.Default)
        {
            throw Error(Peek(), "move and mut receivers require 'self'");
        }
        return new FunctionInputSignature(ParseTypeAnnotation(), FunctionInputOwnership.Default);
    }

    private BlockBody ParseFunctionBlockBody()
    {
        var statements = new List<Statement>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            if (!IsReturnStatement() && !IsGuardLoopControlStatement() && !CheckIdentifier("break") && !CheckIdentifier("continue") && !CheckIdentifier("stop") && TryParseBlockValue(out var value))
            {
                return new BlockBody(statements, value, value.Line, value.Column);
            }

            statements.AddRange(ParseStatement());
            SkipNewLines();
        }

        return new BlockBody(statements, null, Peek().Line, Peek().Column);
    }

    private string ParseTypeAnnotation()
    {
        if (Match(TokenKind.LeftParen, out var productStart))
        {
            var fields = new List<string>();
            var labels = new HashSet<string>(StringComparer.Ordinal);
            while (true)
            {
                string? label = null;
                if (Check(TokenKind.Identifier) && CheckNext(TokenKind.Colon))
                {
                    var labelToken = ExpectIdentifier();
                    Expect(TokenKind.Colon);
                    if (!labels.Add(labelToken.Text))
                    {
                        throw Error(labelToken, $"duplicate product field label '{labelToken.Text}'");
                    }
                    label = labelToken.Text;
                }
                var fieldType = ParseTypeAnnotation();
                fields.Add(label is null ? fieldType : label + ": " + fieldType);
                if (!Match(TokenKind.Comma, out _)) break;
                if (Check(TokenKind.RightParen)) break;
            }
            Expect(TokenKind.RightParen);
            if (fields.Count < 2)
            {
                throw Error(productStart, "product types require at least two fields");
            }
            return "(" + string.Join(", ", fields) + ")";
        }

        if (CheckIdentifier("ref"))
        {
            ExpectIdentifier("ref");
            return "ref " + ParseTypeAnnotation();
        }

        if (CheckIdentifier("box"))
        {
            ExpectIdentifier("box");
            var elementType = ExpectIdentifier();
            return "box " + ResolveTypePath(ParsePathAfterFirstIdentifier(elementType));
        }

        if (CheckIdentifier("dyn"))
        {
            ExpectIdentifier("dyn");
            var trait = ExpectIdentifier();
            return "dyn " + ResolveTypePath(ParsePathAfterFirstIdentifier(trait));
        }

        if (Match(TokenKind.LeftBracket, out var arrayStart))
        {
            var resolvedElementType = ParseTypeAnnotation();
            if (Match(TokenKind.RightBracket, out _))
            {
                return $"[{resolvedElementType}]";
            }

            Expect(TokenKind.Semicolon);
            if (Match(TokenKind.LessEqual, out _))
            {
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                {
                    throw Error(capacity, "bounded array capacity must be a positive integer literal");
                }
                Expect(TokenKind.RightBracket);
                return $"[{resolvedElementType}; <={parsedCapacity}]";
            }
            if (Match(TokenKind.Number, out var concreteFixedLength))
            {
                if (!int.TryParse(concreteFixedLength.Text, out var parsedLength) || parsedLength < 0)
                {
                    throw Error(concreteFixedLength, "fixed array length must be a nonnegative integer literal");
                }
                Expect(TokenKind.RightBracket);
                return $"[{resolvedElementType}; {parsedLength}]";
            }
            if (Match(TokenKind.Identifier, out var fixedLength))
            {
                Expect(TokenKind.RightBracket);
                return $"[{resolvedElementType}; {fixedLength.Text}]";
            }
            Expect(TokenKind.Tilde);
            Expect(TokenKind.RightBracket);
            return $"[{resolvedElementType}; ~]";
        }

        if (Match(TokenKind.LeftBrace, out var dictStart))
        {
            var keyType = ParseTypeAnnotation();
            Expect(TokenKind.Colon);
            var valueType = ParseTypeAnnotation();
            if (Match(TokenKind.Semicolon, out _))
            {
                Expect(TokenKind.LessEqual);
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                {
                    throw Error(capacity, "bounded dictionary capacity must be a positive integer literal");
                }
                Expect(TokenKind.RightBrace);
                return $"{{{keyType}: {valueType}; <={parsedCapacity}}}";
            }
            Expect(TokenKind.RightBrace);
            return $"{{{keyType}: {valueType}}}";
        }

        var typeName = ExpectIdentifier();
        if ((typeName.Text is "Option" or "Result" or "Stream" or "EventStream" or "BitSet" or "BinaryHeap" or "Deque" or "Set") && Match(TokenKind.Less, out _))
        {
            if (typeName.Text == "BitSet")
            {
                var count = Expect(TokenKind.Number);
                if (!int.TryParse(count.Text, out var parsedCount) || parsedCount <= 0)
                {
                    throw Error(count, "BitSet size must be a positive integer literal");
                }
                Expect(TokenKind.Greater);
                return $"BitSet<{parsedCount}>";
            }
            var first = ParseTypeAnnotation();
            if (typeName.Text is "Option" or "Stream" or "EventStream" or "BinaryHeap" or "Deque" or "Set")
            {
                Expect(TokenKind.Greater);
                return $"{typeName.Text}<{first}>";
            }
            Expect(TokenKind.Comma);
            var second = ParseTypeAnnotation();
            Expect(TokenKind.Greater);
            return $"Result<{first}, {second}>";
        }
        return ResolveTypePath(ParsePathAfterFirstIdentifier(typeName));
    }

    private FunctionInputSignature ParseOptionalInputSignature()
    {
        // FunctionSignature = Arrow TypeAnnotation | InputTypeAnnotation Arrow TypeAnnotation
        if (Check(TokenKind.Arrow))
        {
            return new FunctionInputSignature(null, FunctionInputOwnership.Default);
        }

        var ownership = FunctionInputOwnership.Default;
        if (CheckIdentifier("move"))
        {
            ExpectIdentifier("move");
            ownership = FunctionInputOwnership.Move;
        }
        else if (CheckIdentifier("mut"))
        {
            ExpectIdentifier("mut");
            ownership = FunctionInputOwnership.MutableBorrow;
        }

        return new FunctionInputSignature(ParseTypeAnnotation(), ownership);
    }

    private readonly record struct FunctionInputSignature(string? TypeName, FunctionInputOwnership Ownership);

    private IReadOnlyList<Statement> ParseMainBlock()
    {
        // MainBlock = Identifier("main") LeftBrace NewLine* Statement* RightBrace
        var main = ExpectIdentifier("main");
        if (main.Text != "main")
        {
            throw Error(main, "expected 'main' block");
        }

        Expect(TokenKind.LeftBrace);
        var statements = new List<Statement>();
        SkipNewLines();

        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            statements.AddRange(ParseStatement());
            SkipNewLines();
        }

        Expect(TokenKind.RightBrace);
        return statements;
    }

    private IReadOnlyList<Statement> ParseTopLevelStatements()
    {
        // Source files may omit main; remaining top-level statements become the main body.
        var statements = new List<Statement>();
        SkipNewLines();

        while (!Check(TokenKind.End))
        {
            statements.AddRange(ParseStatement());
            SkipNewLines();
        }

        return statements;
    }

    private IReadOnlyList<Statement> ParseStatement()
    {
        // Statement = ReturnStatement | GuardLoopControlStatement | LoopControlStatement | Identifier("stop") StatementEnd | BlockFunctionCallStatement | EachStatement | BindingStatement | ExpressionStatement
        if (IsReturnStatement())
        {
            return [ParseReturnStatement()];
        }

        if (IsGuardLoopControlStatement())
        {
            return [ParseGuardLoopControlStatement()];
        }

        if (CheckIdentifier("break") || CheckIdentifier("continue"))
        {
            return [ParseLoopControlStatement()];
        }

        if (CheckIdentifier("stop"))
        {
            var stop = ExpectIdentifier("stop");
            ExpectStatementEnd();
            return [new StreamStopStatement(stop.Line, stop.Column)];
        }

        if (TryParseBlockFunctionCallStatement(out var blockFunctionCallStatement))
        {
            return blockFunctionCallStatement;
        }

        return [ParseExpressionStatement()];
    }

    private FunctionInputSignature ParseRequiredInputSignature()
    {
        var signature = ParseOptionalInputSignature();
        if (signature.TypeName is null)
        {
            throw Error(Peek(), "additional function parameter requires a type");
        }
        return signature;
    }

    private Statement ParseLoopControlStatement()
    {
        // LoopControlStatement = (Identifier("break") | Identifier("continue")) StatementEnd
        var keyword = Expect(TokenKind.Identifier);
        ExpectStatementEnd();
        var kind = keyword.Text == "break" ? LoopControlKind.Break : LoopControlKind.Continue;
        return new LoopControlStatement(kind, keyword.Line, keyword.Column);
    }

    private Statement ParseReturnStatement()
    {
        // ReturnStatement = Identifier("return") StatementEnd | RangeOrLogicalExpression Arrow Identifier("return") StatementEnd
        if (CheckIdentifier("return"))
        {
            var keyword = ExpectIdentifier("return");
            ExpectStatementEnd();
            return new ReturnStatement(null, keyword.Line, keyword.Column);
        }

        var value = ParseRangeOrLogicalExpression();
        Expect(TokenKind.Arrow);
        var returnKeyword = ExpectIdentifier("return");
        ExpectStatementEnd();
        return new ReturnStatement(value, returnKeyword.Line, returnKeyword.Column);
    }

    private bool IsReturnStatement()
    {
        if (CheckIdentifier("return"))
        {
            return true;
        }

        var offset = 0;
        var parentheses = 0;
        var brackets = 0;
        var braces = 0;
        while (_index + offset < tokens.Count)
        {
            var kind = tokens[_index + offset].Kind;
            if (parentheses == 0 && brackets == 0 && braces == 0
                && kind is TokenKind.NewLine or TokenKind.RightBrace or TokenKind.End)
            {
                return offset >= 2
                    && CheckAhead(offset - 2, TokenKind.Arrow)
                    && CheckAheadIdentifier(offset - 1, "return");
            }
            switch (kind)
            {
                case TokenKind.LeftParen: parentheses++; break;
                case TokenKind.RightParen: parentheses--; break;
                case TokenKind.LeftBracket: brackets++; break;
                case TokenKind.RightBracket: brackets--; break;
                case TokenKind.LeftBrace: braces++; break;
                case TokenKind.RightBrace when braces > 0: braces--; break;
            }
            offset++;
        }
        return false;
    }

    private Statement ParseGuardLoopControlStatement()
    {
        // GuardLoopControlStatement = RangeOrLogicalExpression Arrow Identifier("if") (Identifier("break") | Identifier("continue")) StatementEnd
        var condition = ParseRangeOrLogicalExpression();
        Expect(TokenKind.Arrow);
        ExpectIdentifier("if");
        var keyword = Expect(TokenKind.Identifier);
        ExpectStatementEnd();
        var kind = keyword.Text == "break" ? LoopControlKind.Break : LoopControlKind.Continue;
        return new GuardLoopControlStatement(condition, kind, keyword.Line, keyword.Column);
    }

    private bool IsGuardLoopControlStatement()
    {
        var offset = 0;
        var parentheses = 0;
        var brackets = 0;
        var braces = 0;
        while (_index + offset < tokens.Count)
        {
            var kind = tokens[_index + offset].Kind;
            if (parentheses == 0 && brackets == 0 && braces == 0
                && kind is TokenKind.NewLine or TokenKind.RightBrace or TokenKind.End)
            {
                return offset >= 3
                    && CheckAhead(offset - 3, TokenKind.Arrow)
                    && CheckAheadIdentifier(offset - 2, "if")
                    && (CheckAheadIdentifier(offset - 1, "break")
                        || CheckAheadIdentifier(offset - 1, "continue"));
            }
            switch (kind)
            {
                case TokenKind.LeftParen: parentheses++; break;
                case TokenKind.RightParen: parentheses--; break;
                case TokenKind.LeftBracket: brackets++; break;
                case TokenKind.RightBracket: brackets--; break;
                case TokenKind.LeftBrace: braces++; break;
                case TokenKind.RightBrace when braces > 0: braces--; break;
            }
            offset++;
        }
        return false;
    }

    private bool TryParseLeadingIndexAssignment(out Statement statement)
    {
        // LeadingIndexAssignment = Identifier Bang? LeftBracket Expression RightBracket Equal Expression StatementEnd
        statement = null!;
        var saved = _index;
        if (!Match(TokenKind.Identifier, out var name))
        {
            return false;
        }
        if (Match(TokenKind.Bang, out _))
        {
            name = name with { Text = name.Text + "!" };
        }
        if (!Match(TokenKind.LeftBracket, out _))
        {
            _index = saved;
            return false;
        }
        var index = ParseExpression();
        Expect(TokenKind.RightBracket);
        if (!Match(TokenKind.Equal, out _))
        {
            _index = saved;
            return false;
        }
        var value = ParseExpression();
        ExpectStatementEnd();
        statement = new IndexAssignmentStatement(name.Text, index, value, name.Line, name.Column);
        return true;
    }

    private bool TryParseBlockFunctionCallStatement(out IReadOnlyList<Statement> statement)
    {
        // BlockFunctionCallStatement = RangeOrLogicalExpression (NewLine* Arrow Path FlowTargetCall? ((Identifier (Comma Identifier)*)? LeftBrace NewLine* Statement* RightBrace | NewLine* lookahead(Arrow)))+ (NewLine* FatArrow MutableName)? NewLine*
        statement = null!;

        var saved = _index;

        var source = ParseRangeOrLogicalExpression();

        if (!MatchAfterOptionalNewLines(TokenKind.Arrow, out _))
        {
            _index = saved;
            return false;
        }

        var calls = new List<BlockFunctionCallStatement>();
        Statement? terminalStatement = null;
        while (true)
        {
            var targetToken = ExpectIdentifier();
            if (targetToken.Text is "if" or "unless" or "when" or "fold" or "branch" or "partition"
                || (targetToken.Text == "tap" && Check(TokenKind.LeftBrace) && CheckAheadAfterNewLines(1, TokenKind.Arrow))
                || (targetToken.Text == "parallel" && CheckIdentifier("branch")))
            {
                _index = saved;
                return false;
            }

            var target = ResolveFlowTargetPath(ParsePathAfterFirstIdentifier(targetToken));
            IReadOnlyList<Expression> arguments = Array.Empty<Expression>();
            if (Match(TokenKind.LeftParen, out _))
            {
                arguments = ParseOptionalArgumentList();
                Expect(TokenKind.RightParen);
            }
            if (MatchAfterOptionalNewLines(TokenKind.Arrow, out _))
            {
                var blocklessSyntheticName = "$block_pipeline_" + _syntheticBlockResultIndex++.ToString(CultureInfo.InvariantCulture);
                calls.Add(new BlockFunctionCallStatement(source, target, "it", Array.Empty<Statement>(), blocklessSyntheticName, false, targetToken.Line, targetToken.Column, true, ResultIsSynthetic: true, Arguments: arguments));
                source = new NameExpression(blocklessSyntheticName, targetToken.Line, targetToken.Column, targetToken.ByteOffset);
                continue;
            }
            var itemName = "it";
            var additionalItemNames = new List<string>();
            var usesDefaultItemName = true;
            if (!Check(TokenKind.Identifier) && !Check(TokenKind.LeftBrace))
            {
                _index = saved;
                return false;
            }

            if (Check(TokenKind.Identifier))
            {
                var item = ExpectIdentifier();
                itemName = item.Text;
                usesDefaultItemName = false;
                while (Match(TokenKind.Comma, out _))
                {
                    additionalItemNames.Add(ExpectIdentifier().Text);
                }
            }

            if (!Check(TokenKind.LeftBrace))
            {
                _index = saved;
                return false;
            }

            Expect(TokenKind.LeftBrace);
            var body = new List<Statement>();
            SkipNewLines();

            while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
            {
                body.AddRange(ParseStatement());
                SkipNewLines();
            }

            Expect(TokenKind.RightBrace);
            calls.Add(new BlockFunctionCallStatement(source, target, itemName, body, null, false, targetToken.Line, targetToken.Column, usesDefaultItemName, Arguments: arguments, AdditionalItemNames: additionalItemNames));

            var continuation = _index;
            if (!MatchAfterOptionalNewLines(TokenKind.Arrow, out _))
            {
                break;
            }

            _index = continuation;
            var nextIsBlock = IsBlockFunctionTargetAhead();
            var syntheticName = "$block_pipeline_" + _syntheticBlockResultIndex++.ToString(CultureInfo.InvariantCulture);
            calls[^1] = calls[^1] with { ResultName = syntheticName, ResultIsSynthetic = true };
            source = new NameExpression(syntheticName, calls[^1].Line, calls[^1].Column);
            if (nextIsBlock)
            {
                _ = MatchAfterOptionalNewLines(TokenKind.Arrow, out _);
                continue;
            }
            source = ParseFlowContinuation(source, stopBeforeBlock: true);
            if (MatchAfterOptionalNewLines(TokenKind.Arrow, out _))
                continue;
            terminalStatement = ParseExpressionStatement(source);
            break;
        }
        if (terminalStatement is not null)
        {
            Statement block = calls.Count == 1
                ? calls[0]
                : new BlockFunctionPipelineStatement(calls, calls[0].Line, calls[0].Column);
            statement = [block, terminalStatement];
            return true;
        }
        if (MatchAfterOptionalNewLines(TokenKind.FatArrow, out _))
        {
            var result = ExpectIdentifier();
            var resultName = result.Text;
            var resultIsMutable = false;
            if (Match(TokenKind.Bang, out _))
            {
                resultName += "!";
                resultIsMutable = true;
            }
            calls[^1] = calls[^1] with { ResultName = resultName, ResultIsMutable = resultIsMutable };
            ExpectStatementEnd();
        }
        else
        {
            ExpectStatementEnd();
        }

        statement = [calls.Count == 1
            ? calls[0]
            : new BlockFunctionPipelineStatement(calls, calls[0].Line, calls[0].Column)];
        return true;
    }

    private Statement ParseEachStatement()
    {
        // EachStatement = Identifier("each") Identifier Identifier("in") RangeExpression LeftBrace NewLine* Statement* RightBrace
        var each = ExpectIdentifier("each");
        var item = ExpectIdentifier();
        ExpectIdentifier("in");
        var source = ParseRangeExpression();
        Expect(TokenKind.LeftBrace);
        var body = new List<Statement>();
        SkipNewLines();

        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            body.AddRange(ParseStatement());
            SkipNewLines();
        }

        Expect(TokenKind.RightBrace);
        return new BlockFunctionCallStatement(source, new[] { "each" }, item.Text, body, null, false, each.Line, each.Column, false);
    }

    private bool TryParseRangeExpression(Expression start, out RangeExpression range)
    {
        // RangeExpression = EqualityExpression Range EqualityExpression
        range = null!;
        var isEndExclusive = false;
        if (Match(TokenKind.RangeUntil, out _))
        {
            isEndExclusive = true;
        }
        else if (!Match(TokenKind.Range, out _))
        {
            return false;
        }

        var end = ParseEqualityExpression();
        range = new RangeExpression(start, end, start.Line, start.Column, isEndExclusive);
        return true;
    }

    private RangeExpression ParseRangeExpression()
    {
        // RangeExpression = EqualityExpression Range EqualityExpression
        var start = ParseEqualityExpression();
        var isEndExclusive = Match(TokenKind.RangeUntil, out _);
        if (!isEndExclusive) Expect(TokenKind.Range);
        var end = ParseEqualityExpression();
        return new RangeExpression(start, end, start.Line, start.Column, isEndExclusive);
    }

    private Statement ParseBindingStatement()
    {
        // BindingStatement = Identifier Equal Expression StatementEnd
        var name = ExpectIdentifier();
        Expect(TokenKind.Equal);
        var expression = ParseExpression();
        ExpectStatementEnd();
        return new BindingStatement(name.Text, expression, name.Line, name.Column, IsMutable: false);
    }

    private Statement ParseStreamStateBindingStatement()
    {
        // stream state declaration = Identifier("state") MutableName Equal Expression StatementEnd
        _ = ExpectIdentifier("state");
        var name = ExpectIdentifier();
        var isMutable = Match(TokenKind.Bang, out _);
        if (isMutable)
        {
            name = name with { Text = name.Text + "!" };
        }
        Expect(TokenKind.Equal);
        var expression = ParseExpression();
        ExpectStatementEnd();
        return new BindingStatement(name.Text, expression, name.Line, name.Column, isMutable, IsStreamState: true);
    }

    private Statement ParseExpressionStatement()
    {
        // ExpressionStatement = Expression (NewLine* FatArrow MutableName)? StatementEnd
        return ParseExpressionStatement(ParseExpression());
    }

    private Statement ParseExpressionStatement(Expression expression)
    {
        if (MatchAfterOptionalNewLines(TokenKind.FatArrow, out _))
        {
            var isStreamState = CheckIdentifier("state") && CheckNext(TokenKind.Identifier);
            if (isStreamState) _ = ExpectIdentifier("state");
            var name = ExpectIdentifier();
            var hasMutableOwnerSuffix = false;
            if (Match(TokenKind.Bang, out _))
            {
                name = name with { Text = name.Text + "!" };
                hasMutableOwnerSuffix = true;
            }
            if (Match(TokenKind.LeftBracket, out _))
            {
                var index = ParseExpression();
                Expect(TokenKind.RightBracket);
                ExpectStatementEnd();
                return new IndexAssignmentStatement(name.Text, index, expression, name.Line, name.Column);
            }

            if (Match(TokenKind.Dot, out _))
            {
                var field = ExpectIdentifier();
                ExpectStatementEnd();
                return new FieldAssignmentStatement(name.Text, field.Text, expression, name.Line, name.Column);
            }

            ExpectStatementEnd();
            return new BindingStatement(name.Text, expression, name.Line, name.Column, hasMutableOwnerSuffix, IsStreamState: isStreamState);
        }

        ExpectStatementEnd();
        return new ExpressionStatement(expression);
    }

    private Expression ParseExpression()
    {
        // Expression = FlowExpression
        return ParseFlowExpression();
    }

    private Expression ParseFlowExpression()
    {
        // FlowExpression = RangeOrLogicalExpression (NewLine* Arrow (Path FlowTargetCall? | IfFlowTarget | WhenFlowTarget | FoldFlowTarget))*
        return ParseFlowContinuation(ParseRangeOrLogicalExpression());
    }

    private Expression ParseFlowContinuation(Expression expression, bool stopBeforeBlock = false)
    {
        List<FlowTarget>? targets = null;
        while ((!stopBeforeBlock || !IsBlockFunctionTargetAhead()) && MatchAfterOptionalNewLines(TokenKind.Arrow, out _))
        {
            var target = ExpectIdentifier();
            if (target.Text is "if" or "unless")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                var thenBody = ParseBlockBody();
                BlockBody? elseBody = null;
                if (target.Text == "if" && CheckIdentifier("else"))
                {
                    ExpectIdentifier("else");
                    elseBody = ParseBlockBody();
                }

                var condition = target.Text == "unless"
                    ? new NotExpression(expression, target.Line, target.Column)
                    : expression;
                expression = new IfExpression(condition, thenBody, elseBody, target.Line, target.Column);
                continue;
            }

            if (target.Text == "when")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParseSubjectWhenExpression(expression, target);
                continue;
            }

            if (target.Text == "fold")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParseFoldExpression(expression, target);
                continue;
            }

            if (target.Text == "branch")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParseBranchExpression(expression, target, isParallel: false);
                continue;
            }

            if (target.Text == "parallel" && CheckIdentifier("branch"))
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                ExpectIdentifier("branch");
                expression = ParseBranchExpression(expression, target, isParallel: true);
                continue;
            }

            if (target.Text == "tap")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParseTapExpression(expression, target);
                continue;
            }

            if (target.Text == "partition")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParsePartitionExpression(expression, target);
                continue;
            }

            if (target.Text is "zip" or "merge" or "concat" or "latest")
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                var policy = target.Text switch
                {
                    "zip" => StreamJoinPolicy.Zip,
                    "merge" => StreamJoinPolicy.Merge,
                    "concat" => StreamJoinPolicy.Concat,
                    "latest" => StreamJoinPolicy.Latest,
                    _ => throw new InvalidOperationException("unknown stream join policy")
                };
                expression = new StreamJoinExpression(expression, policy, target.Line, target.Column);
                continue;
            }

            if (target.Text == "each" && (Check(TokenKind.LeftBrace) || (Check(TokenKind.Identifier) && CheckNext(TokenKind.LeftBrace))))
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                var itemName = Check(TokenKind.Identifier) ? ExpectIdentifier().Text : "it";
                Expect(TokenKind.LeftBrace);
                SkipNewLines();
                var selector = ParseExpression();
                Expression? dictionaryValueSelector = null;
                if (Match(TokenKind.Colon, out _))
                {
                    dictionaryValueSelector = ParseExpression();
                }
                SkipNewLines();
                Expect(TokenKind.RightBrace);
                expression = new CompileTimeEachExpression(expression, itemName, selector, dictionaryValueSelector, target.Line, target.Column);
                continue;
            }

            if ((target.Text == "Option" || target.Text == "Result") && Check(TokenKind.Less))
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParseStandardGenericEnumFlowTarget(expression, target);
                continue;
            }

            var path = ResolveFlowTargetPath(ParsePathAfterFirstIdentifier(target));
            string? typeArgument = null;
            int? compileTimeValueArgument = null;
            if (Match(TokenKind.Less, out _))
            {
                if (Check(TokenKind.Number))
                {
                    var valueArgument = Expect(TokenKind.Number);
                    if (!int.TryParse(valueArgument.Text, out var parsedValueArgument) || parsedValueArgument < 0)
                    {
                        throw Error(valueArgument, "compile-time value argument must be a non-negative Int literal");
                    }
                    compileTimeValueArgument = parsedValueArgument;
                }
                else
                {
                    typeArgument = ParseTypeAnnotation();
                }
                Expect(TokenKind.Greater);
            }
            var usesCallSyntax = false;
            if (Match(TokenKind.LeftParen, out _))
            {
                usesCallSyntax = true;
                var arguments = ParseOptionalArgumentList();
                Expect(TokenKind.RightParen);
                targets ??= [];
                targets.Add(new FlowTarget(path, arguments, usesCallSyntax, typeArgument, compileTimeValueArgument, target.Line, target.Column, GetOpenImportCandidates(path), target.ByteOffset) { SourceLine = target.SourceLine, SourceColumn = target.SourceColumn });
                continue;
            }
            targets ??= [];
            targets.Add(new FlowTarget(path, [], usesCallSyntax, typeArgument, compileTimeValueArgument, target.Line, target.Column, GetOpenImportCandidates(path), target.ByteOffset) { SourceLine = target.SourceLine, SourceColumn = target.SourceColumn });
        }

        expression = BuildFlowExpression(expression, targets);
        while (Match(TokenKind.Question, out var question))
        {
            expression = new TryExpression(expression, question.Line, question.Column);
        }
        return expression;
    }

    private Expression ParseStandardGenericEnumFlowTarget(Expression source, Token typeName)
    {
        Expect(TokenKind.Less);
        var first = ParseTypeAnnotation();
        string specialized;
        if (typeName.Text == "Option")
        {
            Expect(TokenKind.Greater);
            specialized = $"Option<{first}>";
        }
        else
        {
            Expect(TokenKind.Comma);
            var second = ParseTypeAnnotation();
            Expect(TokenKind.Greater);
            specialized = $"Result<{first}, {second}>";
        }
        Expect(TokenKind.Dot);
        var variant = ExpectIdentifier();
        var arguments = new List<Expression> { source };
        if (Match(TokenKind.LeftParen, out _))
        {
            if (!Check(TokenKind.RightParen)) ParseArgumentList(arguments);
            Expect(TokenKind.RightParen);
        }
        return new CallExpression(new[] { specialized, variant.Text }, arguments, typeName.Line, typeName.Column);
    }

    private Expression ParseBranchExpression(Expression source, Token keyword, bool isParallel)
    {
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var arms = new List<BranchArm>();
        var labels = new HashSet<string>(StringComparer.Ordinal);
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            var label = ExpectIdentifier();
            if (!labels.Add(label.Text))
            {
                throw Error(label, $"duplicate branch label '{label.Text}'");
            }
            Expect(TokenKind.Colon);
            var mode = BranchInputMode.Default;
            if (CheckIdentifier("ref"))
            {
                ExpectIdentifier("ref");
                mode = BranchInputMode.ReadonlyBorrow;
            }
            else if (CheckIdentifier("mut"))
            {
                ExpectIdentifier("mut");
                mode = BranchInputMode.MutableBorrow;
            }
            else if (CheckIdentifier("move"))
            {
                ExpectIdentifier("move");
                mode = BranchInputMode.Move;
            }
            Expect(TokenKind.Arrow);
            var armTargets = ParseJunctionTargetChain();
            arms.Add(new BranchArm(label.Text, mode, armTargets, label.Line, label.Column));
            if (!Check(TokenKind.RightBrace) && Peek().Line <= armTargets[^1].Line)
            {
                throw Error(Peek(), "branch arms must be separated by a newline");
            }
        }
        Expect(TokenKind.RightBrace);
        if (arms.Count < 2)
        {
            throw Error(keyword, "branch requires at least two arms");
        }
        return new BranchExpression(source, arms, isParallel, keyword.Line, keyword.Column);
    }

    private Expression ParseTapExpression(Expression source, Token keyword)
    {
        IReadOnlyList<FlowTarget> targets;
        if (Match(TokenKind.LeftBrace, out _))
        {
            SkipNewLines();
            Expect(TokenKind.Arrow);
            targets = ParseJunctionTargetChain();
            Expect(TokenKind.RightBrace);
        }
        else
        {
            targets = [ParseJunctionTarget()];
        }
        return new TapExpression(source, targets, keyword.Line, keyword.Column);
    }

    private Expression ParsePartitionExpression(Expression source, Token keyword)
    {
        var itemName = Check(TokenKind.Identifier) ? ExpectIdentifier().Text : "it";
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var arms = new List<PartitionArm>();
        var labels = new HashSet<string>(StringComparer.Ordinal);
        var sawElse = false;
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            var label = ExpectIdentifier();
            if (!labels.Add(label.Text))
            {
                throw Error(label, $"duplicate partition label '{label.Text}'");
            }
            Expect(TokenKind.Colon);
            if (CheckIdentifier("else"))
            {
                ExpectIdentifier("else");
                if (sawElse)
                {
                    throw Error(label, "partition requires exactly one else route");
                }
                sawElse = true;
                arms.Add(new PartitionArm(label.Text, null, label.Line, label.Column));
            }
            else
            {
                if (sawElse)
                {
                    throw Error(label, "partition else route must be last");
                }
                ExpectIdentifier("when");
                arms.Add(new PartitionArm(label.Text, ParseExpression(), label.Line, label.Column));
            }
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        if (!sawElse)
        {
            throw Error(keyword, "partition requires one final else route");
        }
        if (arms.Count < 2)
        {
            throw Error(keyword, "partition requires at least two routes");
        }
        return new PartitionExpression(source, itemName, arms, keyword.Line, keyword.Column);
    }

    private IReadOnlyList<FlowTarget> ParseJunctionTargetChain()
    {
        var targets = new List<FlowTarget> { ParseJunctionTarget() };
        while (true)
        {
            SkipNewLines();
            if (!Match(TokenKind.Arrow, out _)) break;
            targets.Add(ParseJunctionTarget());
        }
        return targets;
    }

    private FlowTarget ParseJunctionTarget()
    {
        var first = ExpectIdentifier();
        var path = ResolveFlowTargetPath(ParsePathAfterFirstIdentifier(first));
        string? typeArgument = null;
        int? compileTimeValueArgument = null;
        if (Match(TokenKind.Less, out _))
        {
            if (Check(TokenKind.Number))
            {
                var valueArgument = Expect(TokenKind.Number);
                if (!int.TryParse(valueArgument.Text, out var parsed) || parsed < 0)
                {
                    throw Error(valueArgument, "compile-time value argument must be a non-negative Int literal");
                }
                compileTimeValueArgument = parsed;
            }
            else
            {
                typeArgument = ParseTypeAnnotation();
            }
            Expect(TokenKind.Greater);
        }
        var usesCallSyntax = Match(TokenKind.LeftParen, out _);
        IReadOnlyList<Expression> arguments = [];
        if (usesCallSyntax)
        {
            arguments = ParseOptionalArgumentList();
            Expect(TokenKind.RightParen);
        }
        return new FlowTarget(path, arguments, usesCallSyntax, typeArgument, compileTimeValueArgument, first.Line, first.Column, GetOpenImportCandidates(path), first.ByteOffset) { SourceLine = first.SourceLine, SourceColumn = first.SourceColumn };
    }

    private Expression ParseRangeOrLogicalExpression()
    {
        // RangeOrLogicalExpression = RangeExpression | LogicalOrExpression
        // Both alternatives share this prefix. Rewinding reparses nested calls
        // twice at every depth, so continue from the already parsed value.
        var prefix = ParseEqualityExpression();
        return TryParseRangeExpression(prefix, out var range)
            ? range
            : ParseLogicalOrExpression(prefix);
    }

    private static Expression BuildFlowExpression(Expression expression, List<FlowTarget>? targets)
    {
        return targets is null
            ? expression
            : new FlowExpression(expression, targets, expression.Line, expression.Column);
    }

    private FoldExpression ParseFoldExpression(Expression source, Token fold)
    {
        // FoldFlowTarget = Identifier("fold") Expression (Identifier Comma Identifier)? LeftBrace BlockBody RightBrace
        var initial = ParseExpression();
        var accumulatorName = "acc";
        var itemName = "it";
        if (!Check(TokenKind.LeftBrace))
        {
            accumulatorName = ExpectIdentifier().Text;
            Expect(TokenKind.Comma);
            itemName = ExpectIdentifier().Text;
        }
        var body = ParseBlockBody();
        return new FoldExpression(source, initial, accumulatorName, itemName, body, fold.Line, fold.Column);
    }

    private BlockBody ParseBlockBody()
    {
        // BlockBody = NewLine* Statement* Expression? NewLine*
        var start = Expect(TokenKind.LeftBrace);
        var statements = new List<Statement>();
        SkipNewLines();

        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            if (!IsReturnStatement() && !IsGuardLoopControlStatement() && !CheckIdentifier("break") && !CheckIdentifier("continue") && !CheckIdentifier("stop") && TryParseBlockValue(out var value))
            {
                Expect(TokenKind.RightBrace);
                return new BlockBody(statements, value, start.Line, start.Column);
            }

            statements.AddRange(ParseStatement());
            SkipNewLines();
        }

        Expect(TokenKind.RightBrace);
        return new BlockBody(statements, null, start.Line, start.Column);
    }

    private bool TryParseBlockValue(out Expression value)
    {
        var saved = _index;
        try
        {
            value = ParseExpression();
        }
        catch (SollangException)
        {
            _index = saved;
            value = null!;
            return false;
        }
        SkipNewLines();
        // A bare each at a block tail is a runtime statement, not a collection expansion.
        if (Check(TokenKind.RightBrace) && value is not CompileTimeEachExpression)
        {
            return true;
        }

        _index = saved;
        value = null!;
        return false;
    }

    private Expression ParseLogicalOrExpression(Expression? prefix = null)
    {
        // LogicalOrExpression = LogicalAndExpression (NewLine* Identifier("or") LogicalAndExpression)*
        var expression = ParseLogicalAndExpression(prefix);
        while (MatchIdentifierAfterOptionalNewLines("or", out var op))
        {
            var right = ParseLogicalAndExpression();
            expression = new OrExpression(expression, right, op.Line, op.Column);
        }

        return expression;
    }

    private Expression ParseLogicalAndExpression(Expression? prefix = null)
    {
        // LogicalAndExpression = ValueFlowComparisonExpression (NewLine* Identifier("and") ValueFlowComparisonExpression)*
        var expression = ParseValueFlowComparisonExpression(prefix);
        while (MatchIdentifierAfterOptionalNewLines("and", out var op))
        {
            var right = ParseValueFlowComparisonExpression();
            expression = new AndExpression(expression, right, op.Line, op.Column);
        }

        return expression;
    }

    private Expression ParseEqualityExpression()
    {
        // EqualityExpression = ComparisonExpression ((EqualEqual | BangEqual) ComparisonExpression)*
        var expression = ParseComparisonExpression();
        while (Match(TokenKind.EqualEqual, out var equal) || Match(TokenKind.BangEqual, out equal))
        {
            var op = equal.Kind == TokenKind.EqualEqual ? ComparisonOperator.Equal : ComparisonOperator.NotEqual;
            var right = ParseComparisonExpression();
            expression = new CompareExpression(expression, op, right, equal.Line, equal.Column);
        }

        return expression;
    }

    private Expression ParseComparisonExpression()
    {
        // ComparisonExpression = AdditiveExpression ((Less | LessEqual | Greater | GreaterEqual) AdditiveExpression)*
        var expression = ParseAdditiveExpression();
        while (TryParseComparisonOperator(out var op, out var token))
        {
            var right = ParseAdditiveExpression();
            expression = new CompareExpression(expression, op, right, token.Line, token.Column);
        }

        return expression;
    }

    private Expression ParseValueFlowComparisonExpression(Expression? prefix = null)
    {
        var expression = ParseValueFlowExpression(prefix);
        while (true)
        {
            ComparisonOperator op;
            Token token;
            if (Match(TokenKind.EqualEqual, out token) || Match(TokenKind.BangEqual, out token))
            {
                op = token.Kind == TokenKind.EqualEqual ? ComparisonOperator.Equal : ComparisonOperator.NotEqual;
            }
            else if (!TryParseComparisonOperator(out op, out token))
            {
                break;
            }
            var right = ParseAdditiveExpression();
            expression = new CompareExpression(expression, op, right, token.Line, token.Column);
        }
        return expression;
    }

    private Expression ParseValueFlowExpression(Expression? prefix = null)
    {
        // A regular value transformation binds before comparison and logical operators.
        // Control-flow and junction targets remain at FlowExpression precedence.
        var expression = prefix ?? ParseEqualityExpression();
        List<FlowTarget>? targets = null;
        while (IsValueFlowTargetAhead())
        {
            _ = MatchAfterOptionalNewLines(TokenKind.Arrow, out _);
            var target = ExpectIdentifier();
            if ((target.Text == "Option" || target.Text == "Result") && Check(TokenKind.Less))
            {
                expression = BuildFlowExpression(expression, targets);
                targets = null;
                expression = ParseStandardGenericEnumFlowTarget(expression, target);
                continue;
            }

            var path = ResolveFlowTargetPath(ParsePathAfterFirstIdentifier(target));
            string? typeArgument = null;
            int? compileTimeValueArgument = null;
            if (Match(TokenKind.Less, out _))
            {
                if (Check(TokenKind.Number))
                {
                    var valueArgument = Expect(TokenKind.Number);
                    if (!int.TryParse(valueArgument.Text, out var parsedValueArgument) || parsedValueArgument < 0)
                    {
                        throw Error(valueArgument, "compile-time value argument must be a non-negative Int literal");
                    }
                    compileTimeValueArgument = parsedValueArgument;
                }
                else
                {
                    typeArgument = ParseTypeAnnotation();
                }
                Expect(TokenKind.Greater);
            }
            var usesCallSyntax = Match(TokenKind.LeftParen, out _);
            IReadOnlyList<Expression> arguments = [];
            if (usesCallSyntax)
            {
                arguments = ParseOptionalArgumentList();
                Expect(TokenKind.RightParen);
            }
            targets ??= [];
            targets.Add(new FlowTarget(path, arguments, usesCallSyntax, typeArgument, compileTimeValueArgument, target.Line, target.Column, GetOpenImportCandidates(path), target.ByteOffset) { SourceLine = target.SourceLine, SourceColumn = target.SourceColumn });
        }

        expression = BuildFlowExpression(expression, targets);
        while (Match(TokenKind.Question, out var question))
        {
            expression = new TryExpression(expression, question.Line, question.Column);
        }
        return expression;
    }

    private bool IsValueFlowTargetAhead()
    {
        if (IsBlockFunctionTargetAhead())
        {
            return false;
        }

        var saved = _index;
        if (!MatchAfterOptionalNewLines(TokenKind.Arrow, out _) || !Check(TokenKind.Identifier))
        {
            _index = saved;
            return false;
        }

        var target = Peek().Text;
        _index = saved;
        return target is not ("if" or "unless" or "while" or "when" or "fold" or "branch" or "parallel" or "partition" or "tap" or "zip" or "merge" or "concat" or "latest" or "each" or "return" or "stop");
    }

    private bool IsBlockFunctionTargetAhead()
    {
        var saved = _index;
        try
        {
            if (!MatchAfterOptionalNewLines(TokenKind.Arrow, out _) || !Check(TokenKind.Identifier))
            {
                return false;
            }

            var target = ExpectIdentifier();
            if (target.Text is "if" or "unless" or "when" or "fold" or "branch" or "partition"
                || (target.Text == "parallel" && CheckIdentifier("branch")))
            {
                return false;
            }

            _ = ParsePathAfterFirstIdentifier(target);
            if (Match(TokenKind.LeftParen, out _))
            {
                _ = ParseOptionalArgumentList();
                Expect(TokenKind.RightParen);
            }

            if (Check(TokenKind.Identifier))
            {
                _ = ExpectIdentifier();
                while (Match(TokenKind.Comma, out _))
                {
                    _ = ExpectIdentifier();
                }
            }

            return Check(TokenKind.LeftBrace);
        }
        finally
        {
            _index = saved;
        }
    }

    private bool TryParseComparisonOperator(out ComparisonOperator op, out Token token)
    {
        if (Match(TokenKind.Less, out token))
        {
            op = ComparisonOperator.Less;
            return true;
        }

        if (Match(TokenKind.LessEqual, out token))
        {
            op = ComparisonOperator.LessOrEqual;
            return true;
        }

        if (Match(TokenKind.Greater, out token))
        {
            op = ComparisonOperator.Greater;
            return true;
        }

        if (Match(TokenKind.GreaterEqual, out token))
        {
            op = ComparisonOperator.GreaterOrEqual;
            return true;
        }

        op = default;
        token = default;
        return false;
    }

    private Expression ParseAdditiveExpression()
    {
        // AdditiveExpression = MultiplicativeExpression ((Plus | Minus) MultiplicativeExpression)*
        var expression = ParseMultiplicativeExpression();
        while (Match(TokenKind.Plus, out var op) || Match(TokenKind.Minus, out op))
        {
            var right = ParseMultiplicativeExpression();
            expression = op.Kind == TokenKind.Plus
                ? new AddExpression(expression, right, op.Line, op.Column)
                : new SubtractExpression(expression, right, op.Line, op.Column);
        }

        return expression;
    }

    private Expression ParseMultiplicativeExpression()
    {
        // MultiplicativeExpression = UnaryExpression ((Star | Slash | Percent) UnaryExpression)*
        var expression = ParseUnaryExpression();
        while (Match(TokenKind.Star, out var op) || Match(TokenKind.Slash, out op) || Match(TokenKind.Percent, out op))
        {
            var right = ParseUnaryExpression();
            expression = op.Kind switch
            {
                TokenKind.Star => new MultiplyExpression(expression, right, op.Line, op.Column),
                TokenKind.Slash => new DivideExpression(expression, right, op.Line, op.Column),
                TokenKind.Percent => new ModuloExpression(expression, right, op.Line, op.Column),
                _ => throw Error(op, "expected multiplicative operator")
            };
        }

        return expression;
    }

    private Expression ParseUnaryExpression()
    {
        // UnaryExpression = Identifier("not") UnaryExpression | Minus UnaryExpression | PrimaryExpression
        if (CheckIdentifier("not"))
        {
            var op = ExpectIdentifier("not");
            return new NotExpression(ParseUnaryExpression(), op.Line, op.Column);
        }

        if (CheckIdentifier("box"))
        {
            var keyword = ExpectIdentifier("box");
            return new BoxExpression(ParseUnaryExpression(), keyword.Line, keyword.Column);
        }

        if (Match(TokenKind.Minus, out var minus))
        {
            return new NegateExpression(ParseUnaryExpression(), minus.Line, minus.Column);
        }

        return ParsePrimaryExpression();
    }

    private Expression ParsePrimaryExpression()
    {
        // PrimaryExpression = PostfixExpression
        var expression = ParseAtomExpression();
        while (true)
        {
            if (Match(TokenKind.LeftBracket, out var bracket))
            {
                var index = ParseExpression();
                Expect(TokenKind.RightBracket);
                expression = new IndexExpression(expression, index, bracket.Line, bracket.Column);
                continue;
            }

            if (Match(TokenKind.Bang, out var bang))
            {
                var bracketAfterBang = Expect(TokenKind.LeftBracket);
                var index = ParseExpression();
                Expect(TokenKind.RightBracket);
                expression = new IndexExpression(expression, index, bracketAfterBang.Line, bracketAfterBang.Column);
                continue;
            }

            if (Match(TokenKind.Dot, out var dot))
            {
                var field = ExpectIdentifier();
                expression = new FieldAccessExpression(expression, field.Text, dot.Line, dot.Column);
                continue;
            }

            if (Match(TokenKind.Question, out var question))
            {
                expression = new TryExpression(expression, question.Line, question.Column);
                continue;
            }

            break;
        }

        return expression;
    }

    private Expression ParseAtomExpression()
    {
        // AtomExpression includes text, character, numeric, and name literals.
        if (CheckIdentifier("when"))
        {
            return ParseWhenExpression();
        }

        if (Match(TokenKind.LeftParen, out var productStart))
        {
            var elements = new List<ProductElement>();
            var labels = new HashSet<string>(StringComparer.Ordinal);
            ProductElement ParseElement()
            {
                string? label = null;
                var line = Peek().Line;
                var column = Peek().Column;
                if (Check(TokenKind.Identifier) && CheckNext(TokenKind.Colon))
                {
                    var labelToken = ExpectIdentifier();
                    Expect(TokenKind.Colon);
                    if (!labels.Add(labelToken.Text))
                    {
                        throw Error(labelToken, $"duplicate product field label '{labelToken.Text}'");
                    }
                    label = labelToken.Text;
                    line = labelToken.Line;
                    column = labelToken.Column;
                }
                return new ProductElement(label, ParseExpression(), line, column);
            }
            var first = ParseElement();
            if (!Match(TokenKind.Comma, out _))
            {
                if (first.Label is not null)
                {
                    throw Error(productStart, "a labeled product requires at least two fields");
                }
                Expect(TokenKind.RightParen);
                return first.Value;
            }
            elements.Add(first);
            if (Check(TokenKind.RightParen))
            {
                throw Error(productStart, "product values require at least two fields");
            }
            while (true)
            {
                elements.Add(ParseElement());
                if (!Match(TokenKind.Comma, out _)) break;
                if (Check(TokenKind.RightParen)) break;
            }
            Expect(TokenKind.RightParen);
            return new ProductExpression(elements, productStart.Line, productStart.Column);
        }

        if (Check(TokenKind.LeftBracket))
        {
            return ParseArrayExpression();
        }

        if (Check(TokenKind.LeftBrace))
        {
            return ParseDictionaryExpression();
        }

        if (Match(TokenKind.String, out var stringToken))
        {
            return new StringExpression(StringLiteralParser.ParseStringSegments(stringToken, ParseInterpolationExpressionFragment), stringToken.Line, stringToken.Column);
        }

        if (Match(TokenKind.Number, out var numberToken))
        {
            return new NumberExpression(numberToken.Text, numberToken.Line, numberToken.Column);
        }

        if (Match(TokenKind.Character, out var characterToken))
        {
            return new NumberExpression(characterToken.Text, characterToken.Line, characterToken.Column);
        }

        if (Match(TokenKind.Identifier, out var identifier))
        {
            if (identifier.Text == "map")
            {
                return ParseMapExpression(identifier);
            }
            if (identifier.Text == "true" || identifier.Text == "false")
            {
                return new BoolExpression(identifier.Text == "true", identifier.Line, identifier.Column);
            }
            if ((identifier.Text == "Option" || identifier.Text == "Result") && Check(TokenKind.Less))
            {
                return ParseStandardGenericEnumConstructor(identifier);
            }
            if ((identifier.Text == "Option" || identifier.Text == "Result") && Check(TokenKind.LeftBracket))
            {
                throw Error(Peek(), "generic type arguments use '<...>'; square brackets are reserved for arrays and indexing");
            }

            return ParsePathStartingWith(identifier);
        }

        throw Error(Peek(), "expected expression");
    }

    private Expression ParseMapExpression(Token keyword)
    {
        var modeToken = ExpectIdentifier();
        var mode = modeToken.Text switch
        {
            "read" => MapAccessMode.Read,
            "write" => MapAccessMode.Write,
            _ => throw Error(modeToken, "map expects 'read' or 'write'")
        };
        var path = ParsePrimaryExpression();
        Expression? offset = null;
        Expression? length = null;
        Expression? fileSize = null;
        if (CheckIdentifier("at"))
        {
            ExpectIdentifier("at");
            offset = ParseAdditiveExpression();
            ExpectIdentifier("for");
            length = ParseAdditiveExpression();
        }
        if (CheckIdentifier("size"))
        {
            if (mode != MapAccessMode.Write) throw Error(Peek(), "only map write accepts 'size'");
            ExpectIdentifier("size");
            fileSize = ParseAdditiveExpression();
        }
        return new MapExpression(mode, path, offset, length, fileSize, keyword.Line, keyword.Column);
    }

    private Expression ParseStandardGenericEnumConstructor(Token typeName)
    {
        Expect(TokenKind.Less);
        var first = ParseTypeAnnotation();
        string specialized;
        if (typeName.Text == "Option")
        {
            Expect(TokenKind.Greater);
            specialized = $"Option<{first}>";
        }
        else
        {
            Expect(TokenKind.Comma);
            var second = ParseTypeAnnotation();
            Expect(TokenKind.Greater);
            specialized = $"Result<{first}, {second}>";
        }
        Expect(TokenKind.Dot);
        var variant = ExpectIdentifier();
        if (Match(TokenKind.LeftParen, out _))
        {
            var arguments = new List<Expression>();
            if (!Check(TokenKind.RightParen)) ParseArgumentList(arguments);
            Expect(TokenKind.RightParen);
            return new CallExpression(new[] { specialized, variant.Text }, arguments, typeName.Line, typeName.Column);
        }
        return new FieldAccessExpression(new NameExpression(specialized, typeName.Line, typeName.Column, typeName.ByteOffset), variant.Text, typeName.Line, typeName.Column);
    }

    private Expression ParseStructLiteralExpression(string typeName, int line, int column)
    {
        // StructLiteralExpression = TypeName LeftBrace StructFieldInitializer* RightBrace
        Expect(TokenKind.LeftBrace);
        SkipNewLines();
        var fields = new List<StructFieldInitializer>();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            var field = ExpectIdentifier();
            Expect(TokenKind.Colon);
            var value = ParseExpression();
            fields.Add(new StructFieldInitializer(field.Text, value, field.Line, field.Column));
            var hadComma = Match(TokenKind.Comma, out _);
            if (!hadComma && !Check(TokenKind.NewLine) && !Check(TokenKind.RightBrace))
            {
                throw Error(Peek(), hadComma ? "expected newline or '}' after struct field" : "expected ',' or newline after struct field");
            }
            SkipNewLines();
        }
        Expect(TokenKind.RightBrace);
        return new StructLiteralExpression(typeName, fields, line, column);
    }

    private Expression ParseArrayExpression()
    {
        // ArrayExpression = '[' NewLine* (TypedEmptyArray | ArrayItems) NewLine* ']'
        var start = Expect(TokenKind.LeftBracket);
        SkipNewLines();
        if (Check(TokenKind.Range))
        {
            throw Error(Peek(), "empty growable arrays now require an element type, for example '[Int; ~]'");
        }

        if (Check(TokenKind.RightBracket))
        {
            Expect(TokenKind.RightBracket);
            return new ArrayLiteralExpression([], false, start.Line, start.Column);
        }

        if (Check(TokenKind.Identifier) && CheckNext(TokenKind.Semicolon) && CheckAhead(2, TokenKind.Range))
        {
            throw Error(Peek(), "typed empty growable arrays use '~', for example '[Int; ~]' or '[Int; 1024~]'");
        }

        if (LooksLikeTypedEmptyArrayLiteral())
        {
            var elementType = ExpectIdentifier();
            var resolvedElementType = ResolveTypePath(ParsePathAfterFirstIdentifier(elementType));
            Expect(TokenKind.Semicolon);
            int? capacityHint = null;
            int? boundedCapacity = null;
            if (Match(TokenKind.LessEqual, out _))
            {
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                {
                    throw Error(capacity, "bounded array capacity must be a positive integer literal");
                }

                boundedCapacity = parsedCapacity;
            }
            else if (Match(TokenKind.Number, out var capacity))
            {
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity < 0)
                {
                    throw Error(capacity, "array capacity hint must be a non-negative integer literal");
                }

                capacityHint = parsedCapacity;
            }

            if (boundedCapacity is null) Expect(TokenKind.Tilde);
            SkipNewLines();
            Expect(TokenKind.RightBracket);
            return new TypedEmptyArrayExpression(resolvedElementType, capacityHint, start.Line, start.Column, boundedCapacity);
        }

        if (Check(TokenKind.Identifier) && CheckNext(TokenKind.Semicolon) && CheckAheadAfterNewLines(2, TokenKind.LeftBrace))
        {
            var elementType = ExpectIdentifier();
            Expect(TokenKind.Semicolon);
            SkipNewLines();
            var typedElements = new List<Expression>();
            var typedIsDynamic = false;
            int? typedBoundedCapacity = null;
            while (!Check(TokenKind.RightBracket) && !Check(TokenKind.End))
            {
                typedElements.Add(ParseExpression());
                SkipNewLines();
                if (!Match(TokenKind.Comma, out _)) break;
                SkipNewLines();
            }
            if (Match(TokenKind.Semicolon, out _))
            {
                SkipNewLines();
                if (Match(TokenKind.LessEqual, out _))
                {
                    var capacity = Expect(TokenKind.Number);
                    if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                    {
                        throw Error(capacity, "bounded array capacity must be a positive integer literal");
                    }
                    if (typedElements.Count > parsedCapacity)
                    {
                        throw Error(capacity, "bounded array initializer exceeds its declared capacity");
                    }
                    typedBoundedCapacity = parsedCapacity;
                }
                else
                {
                    Expect(TokenKind.Tilde);
                    typedIsDynamic = true;
                }
                SkipNewLines();
            }
            Expect(TokenKind.RightBracket);
            return new ArrayLiteralExpression(typedElements, typedIsDynamic, start.Line, start.Column, elementType.Text, typedBoundedCapacity);
        }

        var first = ParseExpression();
        if (Match(TokenKind.Semicolon, out _))
        {
            if (Match(TokenKind.Tilde, out _))
            {
                SkipNewLines();
                Expect(TokenKind.RightBracket);
                return new ArrayLiteralExpression([first], IsDynamic: true, start.Line, start.Column);
            }
            if (Match(TokenKind.LessEqual, out _))
            {
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                {
                    throw Error(capacity, "bounded array capacity must be a positive integer literal");
                }
                SkipNewLines();
                Expect(TokenKind.RightBracket);
                return new ArrayLiteralExpression([first], IsDynamic: false, start.Line, start.Column, BoundedCapacity: parsedCapacity);
            }
            var count = Peek();
            if (!Match(TokenKind.Number, out _) && !Match(TokenKind.Identifier, out _))
            {
                throw Error(count, "array repeat count must be a non-negative integer literal or value parameter");
            }
            SkipNewLines();
            Expect(TokenKind.RightBracket);
            var parsedCount = 0;
            if (count.Kind == TokenKind.Number && (!int.TryParse(count.Text, out parsedCount) || parsedCount < 0))
            {
                throw Error(count, "array repeat count must be a non-negative integer literal");
            }

            return count.Kind == TokenKind.Number
                ? new ArrayRepeatExpression(first, parsedCount, null, start.Line, start.Column)
                : new ArrayRepeatExpression(first, null, count.Text, start.Line, start.Column);
        }

        var elements = new List<Expression>();
        AddCompileTimeArrayElements(elements, first, start);
        var isDynamic = false;
        int? seededBoundedCapacity = null;
        while (Match(TokenKind.Comma, out _))
        {
            SkipNewLines();
            if (Match(TokenKind.Tilde, out _))
            {
                throw Error(Peek(), "seeded growable arrays use '; ~', for example '[1, 2; ~]'");
            }

            if (Check(TokenKind.Range))
            {
                throw Error(Peek(), "seeded growable arrays use '; ~', for example '[1, 2; ~]'");
            }

            if (Check(TokenKind.RightBracket))
            {
                break;
            }

            if (Check(TokenKind.Semicolon))
            {
                break;
            }

            AddCompileTimeArrayElements(elements, ParseExpression(), start);
        }

        if (Match(TokenKind.Semicolon, out _))
        {
            SkipNewLines();
            if (Match(TokenKind.LessEqual, out _))
            {
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                {
                    throw Error(capacity, "bounded array capacity must be a positive integer literal");
                }
                if (elements.Count > parsedCapacity)
                {
                    throw Error(capacity, "bounded array initializer exceeds its declared capacity");
                }
                seededBoundedCapacity = parsedCapacity;
            }
            else
            {
                Expect(TokenKind.Tilde);
                isDynamic = true;
            }
        }

        SkipNewLines();
        Expect(TokenKind.RightBracket);
        return new ArrayLiteralExpression(elements, isDynamic, start.Line, start.Column, BoundedCapacity: seededBoundedCapacity);
    }

    private void AddCompileTimeArrayElements(List<Expression> elements, Expression expression, Token start)
    {
        if (expression is RangeExpression range)
        {
            foreach (var item in ExpandCompileTimeRange(range, start))
            {
                elements.Add(new NumberExpression(item.ToString(CultureInfo.InvariantCulture), expression.Line, expression.Column));
            }
            return;
        }

        if (expression is CompileTimeEachExpression each)
        {
            if (each.DictionaryValueSelector is not null)
            {
                throw Error(start, "array compile-time each body must produce one value, not 'key: value'");
            }
            if (each.Source is not RangeExpression sourceRange)
            {
                throw Error(start, "compile-time each currently requires a constant integer range");
            }
            foreach (var item in ExpandCompileTimeRange(sourceRange, start))
            {
                if (!TryEvaluateCompileTimeInt(each.Selector, each.ItemName, item, out var value))
                {
                    throw Error(start, "compile-time each body must be a constant integer expression using its item");
                }
                elements.Add(new NumberExpression(value.ToString(CultureInfo.InvariantCulture), each.Line, each.Column));
            }
            return;
        }

        elements.Add(expression);
    }

    private Expression ParseDictionaryExpression()
    {
        // DictionaryExpression = '{' (TypedEmptyDictionary | DictionaryEntry (',' DictionaryEntry)* ','?) '}'
        var start = Expect(TokenKind.LeftBrace);
        if (Check(TokenKind.RightBrace))
        {
            throw Error(Peek(), "empty dictionary literals require a type, for example '{Int: Int}'");
        }

        if (LooksLikeTypedDictionaryLiteral())
        {
            var keyType = ParseTypeAnnotation();
            Expect(TokenKind.Colon);
            var valueType = ParseTypeAnnotation();
            if (Check(TokenKind.RightBrace))
            {
                Expect(TokenKind.RightBrace);
                return new TypedEmptyDictionaryExpression(keyType, valueType, null, start.Line, start.Column);
            }

            Expect(TokenKind.Semicolon);
            int? capacityHint = null;
            if (Match(TokenKind.LessEqual, out _))
            {
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0)
                {
                    throw Error(capacity, "bounded dictionary capacity must be a positive integer literal");
                }
                Expect(TokenKind.RightBrace);
                return new TypedEmptyDictionaryExpression(keyType, valueType, null, start.Line, start.Column, parsedCapacity);
            }
            if (Check(TokenKind.Number) && CheckNext(TokenKind.Tilde))
            {
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity < 0)
                {
                    throw Error(capacity, "dictionary capacity hint must be a non-negative integer literal");
                }

                capacityHint = parsedCapacity;
                Expect(TokenKind.Tilde);
                Expect(TokenKind.RightBrace);
                return new TypedEmptyDictionaryExpression(keyType, valueType, capacityHint, start.Line, start.Column);
            }

            var typedEntries = ParseDictionaryEntries();
            int? typedBoundedCapacity = null;
            if (Match(TokenKind.Semicolon, out _))
            {
                Expect(TokenKind.LessEqual);
                var capacity = Expect(TokenKind.Number);
                if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0 || typedEntries.Count > parsedCapacity)
                    throw Error(capacity, "bounded dictionary capacity must be positive and at least the initializer count");
                typedBoundedCapacity = parsedCapacity;
            }
            Expect(TokenKind.RightBrace);
            return new DictionaryLiteralExpression(typedEntries, start.Line, start.Column, keyType, valueType, BoundedCapacity: typedBoundedCapacity);
        }

        var entries = ParseDictionaryEntries();
        int? boundedCapacity = null;
        if (Match(TokenKind.Semicolon, out _))
        {
            Expect(TokenKind.LessEqual);
            var capacity = Expect(TokenKind.Number);
            if (!int.TryParse(capacity.Text, out var parsedCapacity) || parsedCapacity <= 0 || entries.Count > parsedCapacity)
                throw Error(capacity, "bounded dictionary capacity must be positive and at least the initializer count");
            boundedCapacity = parsedCapacity;
        }
        Expect(TokenKind.RightBrace);
        return new DictionaryLiteralExpression(entries, start.Line, start.Column, BoundedCapacity: boundedCapacity);
    }

    private IReadOnlyList<DictionaryEntryExpression> ParseDictionaryEntries()
    {
        var entries = new List<DictionaryEntryExpression>();
        SkipNewLines();
        while (!Check(TokenKind.RightBrace) && !Check(TokenKind.Semicolon) && !Check(TokenKind.End))
        {
            var key = ParseExpression();
            if (key is CompileTimeEachExpression each)
            {
                AddCompileTimeDictionaryEntries(entries, each);
                SkipNewLines();
                if (Match(TokenKind.Comma, out _)) SkipNewLines();
                continue;
            }
            Expect(TokenKind.Colon);
            var value = ParseExpression();
            entries.Add(new DictionaryEntryExpression(key, value));
            SkipNewLines();
            if (!Match(TokenKind.Comma, out _))
            {
                break;
            }

            SkipNewLines();
            if (Check(TokenKind.RightBrace))
            {
                break;
            }
        }

        return entries;
    }

    private void AddCompileTimeDictionaryEntries(List<DictionaryEntryExpression> entries, CompileTimeEachExpression each)
    {
        if (each.Source is not RangeExpression sourceRange || each.DictionaryValueSelector is null)
        {
            throw Error(Peek(), "dictionary compile-time each requires a constant range and a 'key: value' body");
        }
        foreach (var item in ExpandCompileTimeRange(sourceRange, Peek()))
        {
            if (!TryEvaluateCompileTimeInt(each.Selector, each.ItemName, item, out var key)
                || !TryEvaluateCompileTimeInt(each.DictionaryValueSelector, each.ItemName, item, out var value))
            {
                throw Error(Peek(), "dictionary compile-time each key and value must be constant integer expressions using its item");
            }
            entries.Add(new DictionaryEntryExpression(
                new NumberExpression(key.ToString(CultureInfo.InvariantCulture), each.Line, each.Column),
                new NumberExpression(value.ToString(CultureInfo.InvariantCulture), each.Line, each.Column)));
        }
    }

    private IReadOnlyList<long> ExpandCompileTimeRange(RangeExpression range, Token token)
    {
        if (!TryEvaluateCompileTimeInt(range.Start, null, 0, out var start)
            || !TryEvaluateCompileTimeInt(range.End, null, 0, out var end))
        {
            throw Error(token, "compile-time range bounds must be constant integer expressions");
        }
        if (end < start)
        {
            throw Error(token, "compile-time range end must be greater than or equal to its start");
        }
        const long maximumElementCount = 100_000;
        var count = checked(end - start + (range.IsEndExclusive ? 0 : 1));
        if (count > maximumElementCount)
        {
            throw Error(token, $"compile-time collection expansion exceeds the {maximumElementCount} element limit");
        }
        var values = new long[checked((int)count)];
        for (long index = 0; index < count; index++) values[index] = checked(start + index);
        return values;
    }

    private static bool TryEvaluateCompileTimeInt(Expression expression, string? itemName, long itemValue, out long value)
    {
        try
        {
            switch (expression)
            {
                case NumberExpression number when !number.Text.Contains('.') && !number.Text.Contains("e", StringComparison.OrdinalIgnoreCase):
                    return long.TryParse(number.Text, NumberStyles.Integer, CultureInfo.InvariantCulture, out value);
                case NameExpression name when itemName is not null && name.Name == itemName:
                    value = itemValue;
                    return true;
                case NegateExpression negate when TryEvaluateCompileTimeInt(negate.Value, itemName, itemValue, out var operand):
                    value = checked(-operand);
                    return true;
                case AddExpression add:
                    return TryEvaluateBinary(add.Left, add.Right, itemName, itemValue, static (left, right) => checked(left + right), out value);
                case SubtractExpression subtract:
                    return TryEvaluateBinary(subtract.Left, subtract.Right, itemName, itemValue, static (left, right) => checked(left - right), out value);
                case MultiplyExpression multiply:
                    return TryEvaluateBinary(multiply.Left, multiply.Right, itemName, itemValue, static (left, right) => checked(left * right), out value);
                case DivideExpression divide:
                    return TryEvaluateBinary(divide.Left, divide.Right, itemName, itemValue, static (left, right) => checked(left / right), out value);
                case ModuloExpression modulo:
                    return TryEvaluateBinary(modulo.Left, modulo.Right, itemName, itemValue, static (left, right) => checked(left % right), out value);
            }
        }
        catch (ArithmeticException)
        {
        }
        value = 0;
        return false;
    }

    private static bool TryEvaluateBinary(Expression leftExpression, Expression rightExpression, string? itemName, long itemValue, Func<long, long, long> operation, out long value)
    {
        if (TryEvaluateCompileTimeInt(leftExpression, itemName, itemValue, out var left)
            && TryEvaluateCompileTimeInt(rightExpression, itemName, itemValue, out var right))
        {
            value = operation(left, right);
            return true;
        }
        value = 0;
        return false;
    }

    private WhenExpression ParseWhenExpression()
    {
        // WhenExpression = Identifier("when") LeftBrace NewLine* WhenArm+ Identifier("else") WhenArmBody NewLine* RightBrace
        var when = ExpectIdentifier("when");
        Expect(TokenKind.LeftBrace);
        var arms = new List<WhenArm>();
        SkipNewLines();

        while (!CheckIdentifier("else") && !Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            var condition = ParseWhenCondition();
            var body = ParseWhenArmBody();
            arms.Add(new WhenArm(condition, body, condition.Line, condition.Column));
            SkipNewLines();
        }

        if (arms.Count == 0)
        {
            throw Error(when, "when requires at least one condition arm");
        }

        ExpectIdentifier("else");
        var elseBody = ParseWhenArmBody();
        SkipNewLines();
        Expect(TokenKind.RightBrace);
        return new WhenExpression(null, arms, elseBody, when.Line, when.Column);
    }

    private Expression ParseSubjectWhenExpression(Expression subject, Token when)
    {
        // WhenFlowTarget = Identifier("when") LeftBrace NewLine* SubjectWhenArm+ Identifier("else") WhenArmBody NewLine* RightBrace
        Expect(TokenKind.LeftBrace);
        var arms = new List<WhenArm>();
        SkipNewLines();

        while (!CheckIdentifier("else") && !Check(TokenKind.RightBrace) && !Check(TokenKind.End))
        {
            var condition = ParseSubjectWhenCondition();
            var body = ParseWhenArmBody();
            arms.Add(new WhenArm(condition, body, condition.Line, condition.Column));
            SkipNewLines();
        }

        if (arms.Count == 0)
        {
            throw Error(when, "when requires at least one condition arm");
        }

        BlockBody? elseBody = null;
        if (CheckIdentifier("else"))
        {
            ExpectIdentifier("else");
            elseBody = ParseWhenArmBody();
        }
        SkipNewLines();
        Expect(TokenKind.RightBrace);
        var usesEnumPatterns = arms.Any(static arm => arm.Condition is EnumPatternExpression);
        if (usesEnumPatterns)
        {
            if (arms.Any(static arm => arm.Condition is not EnumPatternExpression))
            {
                throw Error(when, "enum patterns cannot be mixed with numeric subject conditions");
            }
            return new EnumMatchExpression(subject, arms, elseBody, when.Line, when.Column);
        }
        if (elseBody is null)
        {
            throw Error(when, "numeric subject when requires an else arm");
        }
        return new WhenExpression(subject, arms, elseBody, when.Line, when.Column);
    }

    private Expression ParseWhenCondition()
    {
        // WhenCondition = SubjectWhenCondition | LogicalOrExpression
        var saved = _index;
        if (TryParseSubjectWhenCondition(out var subjectCondition))
        {
            return subjectCondition;
        }

        _index = saved;
        return ParseLogicalOrExpression();
    }

    private BlockBody ParseWhenArmBody()
    {
        // WhenArmBody = FatArrow Expression | Arrow Expression | LeftBrace BlockBody RightBrace
        if (Match(TokenKind.FatArrow, out var arrow))
        {
            return new BlockBody([], ParseExpression(), arrow.Line, arrow.Column);
        }

        return ParseBlockBody();
    }

    private Expression ParseSubjectWhenCondition()
    {
        // SubjectWhenCondition = (EqualEqual | BangEqual | Less | LessEqual | Greater | GreaterEqual) Expression | RangeExpression
        if (Check(TokenKind.Identifier) && !HasSubjectRangeAhead()
            && (CheckNext(TokenKind.Dot)
                || CheckNext(TokenKind.LeftParen)
                || CheckNext(TokenKind.FatArrow)
                || CheckNext(TokenKind.Arrow)
                || CheckNext(TokenKind.LeftBrace)
                || ((Peek().Text == "Option" || Peek().Text == "Result") && CheckNext(TokenKind.Less))))
        {
            return ParseEnumPattern();
        }

        if (TryParseSubjectWhenCondition(out var condition))
        {
            return condition;
        }

        throw Error(Peek(), "expected subject comparison operator or range in value-flow when arm");
    }

    private bool HasSubjectRangeAhead()
    {
        var parentheses = 0;
        var brackets = 0;
        for (var offset = 0; _index + offset < tokens.Count; offset++)
        {
            var kind = tokens[_index + offset].Kind;
            if (parentheses == 0 && brackets == 0)
            {
                if (kind is TokenKind.Range or TokenKind.RangeUntil) return true;
                if (kind is TokenKind.FatArrow or TokenKind.Arrow or TokenKind.LeftBrace or TokenKind.RightBrace or TokenKind.NewLine or TokenKind.End) return false;
            }
            if (kind == TokenKind.LeftParen) parentheses++;
            else if (kind == TokenKind.RightParen && --parentheses < 0) return false;
            else if (kind == TokenKind.LeftBracket) brackets++;
            else if (kind == TokenKind.RightBracket && --brackets < 0) return false;
            if (kind == TokenKind.End) return false;
        }
        return false;
    }

    private EnumPatternExpression ParseEnumPattern()
    {
        // EnumPattern = qualified, payload shorthand, or payloadless shorthand before an arm body
        var start = Peek();
        var isQualified = CheckNext(TokenKind.Dot)
            || ((start.Text == "Option" || start.Text == "Result") && CheckNext(TokenKind.Less));
        var typeName = string.Empty;
        Token variantName;
        if (isQualified)
        {
            if ((start.Text == "Option" || start.Text == "Result") && CheckNext(TokenKind.Less))
            {
                typeName = ParseTypeAnnotation();
                Expect(TokenKind.Dot);
                variantName = ExpectIdentifier();
            }
            else
            {
                var ownerPath = new List<string> { ExpectIdentifier().Text };
                Expect(TokenKind.Dot);
                variantName = ExpectIdentifier();
                while (Match(TokenKind.Dot, out _))
                {
                    ownerPath.Add(variantName.Text);
                    variantName = ExpectIdentifier();
                }
                typeName = ResolveTypePath(ownerPath);
            }
        }
        else
        {
            variantName = ExpectIdentifier();
        }
        Token? binding = null;
        if (Match(TokenKind.LeftParen, out _))
        {
            if (!Check(TokenKind.RightParen))
            {
                binding = ExpectIdentifier();
            }
            Expect(TokenKind.RightParen);
        }
        return new EnumPatternExpression(typeName, variantName.Text, binding?.Text, start.Line, start.Column);
    }

    private bool TryParseSubjectWhenCondition(out Expression condition)
    {
        var saved = _index;
        if (TryParseSubjectWhenOperator(out var op, out var token))
        {
            condition = new SubjectCompareExpression(op, ParseLogicalOrExpression(), token.Line, token.Column);
            return true;
        }

        var start = ParseLogicalOrExpression();
        var isEndExclusive = false;
        if (Match(TokenKind.RangeUntil, out _))
        {
            isEndExclusive = true;
        }
        else if (!Match(TokenKind.Range, out _))
        {
            _index = saved;
            condition = null!;
            return false;
        }

        var end = ParseLogicalOrExpression();
        condition = new SubjectRangeExpression(start, end, start.Line, start.Column, isEndExclusive);
        return true;
    }

    private bool TryParseSubjectWhenOperator(out ComparisonOperator op, out Token token)
    {
        if (Match(TokenKind.EqualEqual, out token))
        {
            op = ComparisonOperator.Equal;
            return true;
        }

        if (Match(TokenKind.BangEqual, out token))
        {
            op = ComparisonOperator.NotEqual;
            return true;
        }

        return TryParseComparisonOperator(out op, out token);
    }

    private Expression ParsePathStartingWith(Token identifier)
    {
        // Path = Identifier (Dot Identifier)*
        var path = ParsePathAfterFirstIdentifier(identifier);
        if (LooksLikeTypeApplication())
        {
            Expect(TokenKind.Less);
            var typeArgument = Check(TokenKind.Number) ? Expect(TokenKind.Number).Text : ParseTypeAnnotation();
            var additionalTypeArguments = new List<string>();
            while (Match(TokenKind.Comma, out _))
            {
                additionalTypeArguments.Add(ParseTypeAnnotation());
            }
            Expect(TokenKind.Greater);
            Expect(TokenKind.LeftParen);
            var arguments = ParseOptionalArgumentList();
            Expect(TokenKind.RightParen);
            return new TypeApplicationExpression(ResolveImportedPath(path), typeArgument, identifier.Line, identifier.Column, arguments, additionalTypeArguments);
        }
        if (Check(TokenKind.LeftBrace))
        {
            return ParseStructLiteralExpression(ResolveTypePath(path), identifier.Line, identifier.Column);
        }
        if (Match(TokenKind.LeftParen, out _))
        {
            return ParseCallExpression(identifier, ResolveImportedPath(path));
        }

        if (path.Count > 1 && _imports.ContainsKey(path[0]))
        {
            var resolved = ResolveImportedPath(path);
            var ownerName = string.Join('.', resolved.Take(resolved.Count - 1));
            return new FieldAccessExpression(
                new NameExpression(ownerName, identifier.Line, identifier.Column, identifier.ByteOffset),
                resolved[^1],
                identifier.Line,
                identifier.Column);
        }

        var name = identifier.Text;
        if (Match(TokenKind.Bang, out _))
        {
            name += "!";
        }

        Expression expression = new NameExpression(name, identifier.Line, identifier.Column, identifier.ByteOffset);
        for (var i = 1; i < path.Count; i++)
        {
            expression = new FieldAccessExpression(expression, path[i], identifier.Line, identifier.Column);
        }
        return expression;
    }

    private IReadOnlyList<string> ParsePathAfterFirstIdentifier(Token identifier)
    {
        // Path = Identifier (Dot Identifier)*
        var path = new List<string> { identifier.Text };
        while (Match(TokenKind.Dot, out _))
        {
            path.Add(ExpectIdentifier().Text);
        }

        return path;
    }

    private string QualifyFunctionName(IReadOnlyList<string> path, bool isLocal)
    {
        if (isLocal || path.Count != 1 || _namespacePath.Count == 0)
        {
            return string.Join('.', path);
        }

        var qualified = new List<string>(_namespacePath.Count + 1);
        foreach (var segment in _namespacePath)
        {
            qualified.Add(segment);
        }

        qualified.Add(path[0]);
        return string.Join('.', qualified);
    }

    private string QualifyMethodOwner(string ownerType)
    {
        // Nominal owners are already namespace-qualified by ResolveTypePath.
        // Built-in owners are not, so retain the declaring module in the
        // method identity. Two modules may intentionally extend UInt64 with
        // the same member name and callers select one through its module.
        if (_namespacePath.Count == 0
            || (!ownerType.StartsWith('[', StringComparison.Ordinal)
                && ownerType.Contains('.', StringComparison.Ordinal)))
        {
            return ownerType;
        }

        return string.Join('.', _namespacePath) + "." + ownerType;
    }

    private bool LooksLikeTypeApplication()
    {
        if (!Check(TokenKind.Less)) return false;
        var savedIndex = _index;
        try
        {
            Advance();
            if (Check(TokenKind.Number)) Advance(); else _ = ParseTypeAnnotation();
            Expect(TokenKind.Greater);
            return Check(TokenKind.LeftParen);
        }
        catch (SollangException)
        {
            return false;
        }
        finally
        {
            _index = savedIndex;
        }
    }

    private bool LooksLikeTypedEmptyArrayLiteral()
    {
        var offset = 0;
        if (!CheckAhead(offset, TokenKind.Identifier)) return false;
        offset++;
        while (CheckAhead(offset, TokenKind.Dot))
        {
            offset++;
            if (!CheckAhead(offset, TokenKind.Identifier)) return false;
            offset++;
        }
        if (!CheckAhead(offset, TokenKind.Semicolon)) return false;
        offset++;
        if (CheckAhead(offset, TokenKind.Tilde)) return true;
        if (CheckAhead(offset, TokenKind.LessEqual) && CheckAhead(offset + 1, TokenKind.Number)) return true;
        return CheckAhead(offset, TokenKind.Number) && CheckAhead(offset + 1, TokenKind.Tilde);
    }

    private bool LooksLikeTypedDictionaryLiteral()
    {
        var savedIndex = _index;
        try
        {
            _ = ParseTypeAnnotation();
            Expect(TokenKind.Colon);
            _ = ParseTypeAnnotation();
            return Check(TokenKind.RightBrace) || Check(TokenKind.Semicolon);
        }
        catch (SollangException)
        {
            return false;
        }
        finally
        {
            _index = savedIndex;
        }
    }

    private string QualifyTypeDeclarationName(string name)
    {
        return _namespacePath.Count == 0 ? name : string.Join('.', _namespacePath) + "." + name;
    }

    private string ResolveTypePath(IReadOnlyList<string> path)
    {
        var resolved = ResolveImportedPath(path);
        if (resolved.Count == 1 && !IsBuiltinTypeName(resolved[0]))
        {
            foreach (var scope in _activeTypeScopes)
            {
                var nestedName = scope + "." + resolved[0];
                if (_knownNestedTypeNames.Contains(nestedName)) return nestedName;
            }
        }
        if (resolved.Count != 1 || _namespacePath.Count == 0 || IsBuiltinTypeName(resolved[0]) || _activeAssociatedTypeNames.Contains(resolved[0]) || _activeGenericParameterNames.Contains(resolved[0]))
        {
            return string.Join('.', resolved);
        }

        return string.Join('.', _namespacePath) + "." + resolved[0];
    }

    private static bool IsBuiltinTypeName(string name)
    {
        return name is "Unit" or "Text" or "Bool" or "Self"
            or "Int" or "Long" or "Int8" or "Int16" or "Int32" or "Int64"
            or "UInt8" or "UInt16" or "UInt32" or "UInt64"
            or "Size" or "UIntSize"
            or "CodePoint"
            or "Arena"
            or "Arguments" or "SourceText" or "MappedBytes" or "MutableMappedBytes"
            or "Float" or "Double" or "Float32" or "Float64";
    }

    private IReadOnlyList<string> ResolveImportedPath(IReadOnlyList<string> path)
    {
        if (path.Count == 0)
        {
            return path;
        }

        IReadOnlyList<string> importedPath;
        if (!_imports.TryGetValue(path[0], out importedPath!) && !_libraryImports.TryGetValue(path[0], out importedPath!))
        {
            if (!_openImports.TryGetValue(path[0], out var candidates))
            {
                return path;
            }

            if (candidates.Count != 1)
            {
                throw new SollangException(ImportDiagnostics.AmbiguousSymbol(path[0], candidates));
            }

            importedPath = candidates[0].Path;
        }

        var resolved = new List<string>(importedPath.Count + path.Count - 1);
        foreach (var segment in importedPath)
        {
            resolved.Add(segment);
        }

        for (var i = 1; i < path.Count; i++)
        {
            resolved.Add(path[i]);
        }

        return resolved;
    }

    private IReadOnlyList<OpenImportCandidate>? GetOpenImportCandidates(IReadOnlyList<string> path) =>
        path.Count == 1 && _openImports.TryGetValue(path[0], out var candidates) && candidates.Count > 1
            ? candidates : null;

    private IReadOnlyList<string> ResolveFlowTargetPath(IReadOnlyList<string> path)
    {
        // A bare flow target may be an inherent method. Preserve it when open
        // imports contain same-named free functions so semantic resolution can
        // prefer the receiver's method before diagnosing a free-call ambiguity.
        if (path.Count == 1
            && _openImports.TryGetValue(path[0], out var candidates)
            && candidates.Count > 1)
        {
            return path;
        }

        return ResolveImportedPath(path);
    }

    private CallExpression ParseCallExpression(Token start, IReadOnlyList<string> path)
    {
        // CallExpression = Path LeftParen ArgumentList? RightParen
        var arguments = ParseOptionalArgumentList();
        Expect(TokenKind.RightParen);
        return new CallExpression(path, arguments, start.Line, start.Column);
    }

    private IReadOnlyList<Expression> ParseOptionalArgumentList()
    {
        var arguments = new List<Expression>();
        SkipNewLines();
        if (!Check(TokenKind.RightParen))
        {
            ParseArgumentList(arguments);
        }
        SkipNewLines();

        return arguments;
    }

    private void ParseArgumentList(List<Expression> arguments)
    {
        // ArgumentList = Expression (Comma Expression)*
        while (true)
        {
            SkipNewLines();
            arguments.Add(ParseExpression());
            SkipNewLines();
            if (!Match(TokenKind.Comma, out _)) break;
        }
    }

    private void ExpectStatementEnd()
    {
        // StatementEnd = NewLine+ | lookahead(RightBrace) | lookahead(End)
        if (Check(TokenKind.NewLine) || Check(TokenKind.RightBrace) || Check(TokenKind.End))
        {
            return;
        }

        throw Error(Peek(), "expected end of statement");
    }

    private void SkipNewLines()
    {
        while (Check(TokenKind.NewLine))
        {
            Advance();
        }
    }

    private bool MatchAfterOptionalNewLines(TokenKind kind, out Token token)
    {
        var saved = _index;
        SkipNewLines();
        if (Match(kind, out token))
        {
            return true;
        }

        _index = saved;
        return false;
    }

    private bool MatchIdentifierAfterOptionalNewLines(string text, out Token token)
    {
        var saved = _index;
        SkipNewLines();
        if (CheckIdentifier(text))
        {
            token = ExpectIdentifier(text);
            return true;
        }

        _index = saved;
        token = default;
        return false;
    }

    private Token Expect(TokenKind kind)
    {
        if (Match(kind, out var token))
        {
            return token;
        }

        throw Error(Peek(), $"expected {kind}");
    }

    private Token ExpectIdentifier(string? text = null)
    {
        var token = Expect(TokenKind.Identifier);
        if (text is not null && token.Text != text)
        {
            throw Error(token, $"expected '{text}'");
        }

        return token;
    }

    private bool Match(TokenKind kind, out Token token)
    {
        if (Check(kind))
        {
            token = Advance();
            return true;
        }

        token = default;
        return false;
    }

    private bool Check(TokenKind kind)
    {
        return Peek().Kind == kind;
    }

    private bool CheckIdentifier(string text)
    {
        return Check(TokenKind.Identifier) && Peek().Text == text;
    }

    private bool CheckDeclarationStart(string keyword)
    {
        return CheckIdentifier(keyword)
            || (CheckIdentifier("public")
                && _index + 1 < tokens.Count
                && tokens[_index + 1].Kind == TokenKind.Identifier
                && tokens[_index + 1].Text == keyword);
    }

    private bool CheckStructDeclarationStart()
    {
        var offset = 0;
        if (CheckAhead(offset, TokenKind.Identifier) && tokens[_index + offset].Text == "public") offset++;
        if (CheckAhead(offset, TokenKind.Identifier) && tokens[_index + offset].Text == "abi") offset++;
        return CheckAhead(offset, TokenKind.Identifier) && tokens[_index + offset].Text == "struct";
    }

    private bool IsFunctionDeclarationStart()
    {
        if (!Check(TokenKind.Identifier))
        {
            return false;
        }

        var offset = CheckIdentifier("public") ? 2 : 1;
        while (CheckAhead(offset, TokenKind.Dot))
        {
            offset++;
            if (!CheckAhead(offset, TokenKind.Identifier))
            {
                return false;
            }

            offset++;
        }

        if (CheckAhead(offset, TokenKind.Less))
        {
            var depth = 0;
            do
            {
                if (CheckAhead(offset, TokenKind.End) || CheckAhead(offset, TokenKind.NewLine)) return false;
                if (CheckAhead(offset, TokenKind.Less)) depth++;
                else if (CheckAhead(offset, TokenKind.Greater)) depth--;
                offset++;
            } while (depth > 0);
            if (depth != 0) return false;
        }

        return CheckAhead(offset, TokenKind.Colon)
            || (CheckAhead(offset, TokenKind.Identifier) && CheckAhead(offset + 1, TokenKind.Colon));
    }

    private bool CheckNext(TokenKind kind)
    {
        return _index + 1 < tokens.Count && tokens[_index + 1].Kind == kind;
    }

    private bool CheckAhead(int offset, TokenKind kind)
    {
        return _index + offset < tokens.Count && tokens[_index + offset].Kind == kind;
    }

    private bool CheckAheadAfterNewLines(int offset, TokenKind kind)
    {
        while (CheckAhead(offset, TokenKind.NewLine)) offset++;
        return CheckAhead(offset, kind);
    }

    private bool CheckAheadIdentifier(int offset, string text)
    {
        return _index + offset < tokens.Count
            && tokens[_index + offset].Kind == TokenKind.Identifier
            && tokens[_index + offset].Text == text;
    }

    private Token Advance()
    {
        return tokens[_index++];
    }

    private Token Peek()
    {
        return tokens[_index];
    }

    private static SollangException Error(Token token, string message)
    {
        return new SollangException($"parse error at {token.Line}:{token.Column}: {message}");
    }
}
